def current_lang() -> str:
    return st.session_state.get("language", "English")


# ============================================================
# CARE Runtime v19.0 — Language Selector Recovery
# Restores the missing language_selector() used by the v12.8.1
# robust sidebar. Language selection improves access only.
# It does not create authority, bind, permission or execution.
# ============================================================

def language_selector() -> str:
    options = ["English", "Dansk"]
    current = st.session_state.get("language", "English")
    if current not in options:
        current = "English"
        st.session_state["language"] = current

    try:
        selected = st.sidebar.radio(
            "Language / Sprog",
            options,
            index=options.index(current),
            key="language",
            horizontal=True,
        )
    except Exception:
        selected = st.session_state.get("language", "English")
        if selected not in options:
            selected = "English"
            st.session_state["language"] = selected

    return selected


def t(key: str) -> str:
    lang = current_lang()
    return TEXT.get(lang, TEXT["English"]).get(key, TEXT["English"].get(key, key))

def page_label(page_key: str) -> str:
    lang = current_lang()
    return PAGE_LABELS.get(lang, PAGE_LABELS["English"]).get(page_key, PAGE_LABELS["English"].get(page_key, page_key))

def group_label(group_key: str) -> str:
    lang = current_lang()
    return GROUP_LABELS.get(lang, GROUP_LABELS["English"]).get(group_key, GROUP_LABELS["English"].get(group_key, group_key))

def hero_text(page_key: str) -> Tuple[str, str, str]:
    lang = current_lang()
    if page_key in HERO:
        return HERO[page_key].get(lang, HERO[page_key]["English"])
    name = page_label(page_key)
    if lang == "Dansk":
        return name, f"Dette modul er en del af {PLATFORM_NAME}. Det er kun observatør-lag og kan ikke autorisere konsekvens.", "CARE Runtime"
    return name, f"This module is part of {PLATFORM_NAME}. It remains observer-only and cannot authorize consequence.", "CARE Runtime"


