def ui_text(value: Any) -> str:
    s = str(value)
    if current_lang() != "Dansk":
        return s
    if s in DA_TRANSLATIONS:
        return DA_TRANSLATIONS[s]
    if s.startswith("### "):
        return "### " + DA_TRANSLATIONS.get(s[4:], s[4:])
    if " matching cycles. Search is visibility only and grants no authority." in s:
        return s.replace(" matching cycles. Search is visibility only and grants no authority.", " matchende cycles. Søgning er kun synlighed og giver ingen autoritet.")
    return s

def display_value(value: Any) -> str:
    return ui_text(value)

def badge_html(value: Any) -> str:
    raw = str(value)
    shown = escape(display_value(raw))
    lower = raw.lower()
    cls = "status-no"
    if lower in ["pass", "bestået", "yes", "ja", "valid", "verified", "fresh", "present"]:
        cls = "status-pass"
    elif lower in ["hold", "unknown", "ukendt", "not verified", "stale"]:
        cls = "status-hold"
    elif lower in ["fail", "fejl", "no", "nej", "invalid", "missing", "broken"]:
        cls = "status-fail" if lower not in ["no", "nej"] else "status-no"
    return f"<span class='status-badge {cls}'>{shown}</span>"

def maybe_badge(header: str, value: Any) -> str:
    h = str(header).lower()
    v = str(value)
    if h in ["status", "authority", "autoritet", "allowed", "tilladt", "state", "tilstand", "result", "resultat", "decision", "beslutning"] or v.lower() in ["pass","fail","hold","no","yes","unknown","present","valid","invalid","verified","fresh","stale","missing"]:
        return badge_html(v)
    return escape(display_value(v))

def care_selectbox(label, options, *args, **kwargs):
    original_format = kwargs.pop("format_func", lambda x: x)
    def fmt(x):
        return display_value(original_format(x))
    return st.selectbox(ui_text(label), options, *args, format_func=fmt, **kwargs)

def care_multiselect(label, options, *args, **kwargs):
    original_format = kwargs.pop("format_func", lambda x: x)
    def fmt(x):
        return display_value(original_format(x))
    return st.multiselect(ui_text(label), options, *args, format_func=fmt, **kwargs)

def care_text_input(label, value="", *args, **kwargs):
    return st.text_input(ui_text(label), ui_text(value), *args, **kwargs)

def care_text_area(label, value="", *args, **kwargs):
    return st.text_area(ui_text(label), ui_text(value), *args, **kwargs)

def care_form_submit_button(label, *args, **kwargs):
    return st.form_submit_button(ui_text(label), *args, **kwargs)


