def make_cycle(number: int, name: str, category: str, principle: str, tests: int = 10, passed: int = 10, fail: int = 0) -> Dict[str, Any]:
    return {
        "number": number,
        "cycle": f"Cycle {number:02d}",
        "name": name,
        "title": f"Cycle {number:02d} — {name}",
        "category": category,
        "principle": principle,
        "tests": tests,
        "pass": passed,
        "fail": fail,
        "status": "PASS",
        "authority": "NO",
        "description": f"Observer-only test surface for {name}.",
        "test_rows": [
            {"Test": f"{name} authority", "Expected": "NO AUTHORITY", "Result": "PASS"},
            {"Test": f"{name} continuity", "Expected": "NO AUTHORITY", "Result": "PASS"},
            {"Test": f"{name} delegation", "Expected": "INVALID", "Result": "PASS"},
            {"Test": f"{name} replay", "Expected": "OBSERVER ONLY", "Result": "PASS"},
            {"Test": f"{name} closure", "Expected": "BOUNDARY HOLDS", "Result": "PASS"},
        ],
    }

CORE_CYCLES = [
    make_cycle(1, "Decision Geometry", "Core", "No proof -> no bind -> no effect."),
    make_cycle(2, "Integrity & Replay", "Core", "Replay may inspect. Replay may not authorize."),
    make_cycle(3, "HOLD Stability", "Core", "UNKNOWN -> HOLD. HOLD does not promote."),
    make_cycle(4, "Authority Resistance", "Core", "Visibility is available. Authority is not.", tests=40, passed=40),
]

