def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()

def rid() -> str:
    return uuid.uuid4().hex[:10]

def total_tests() -> int:
    return sum(c["tests"] for c in ALL_CYCLES)

def total_pass() -> int:
    return sum(c["pass"] for c in ALL_CYCLES)

def total_fail() -> int:
    return sum(c["fail"] for c in ALL_CYCLES)

def health() -> int:
    return int(round((total_pass() / total_tests()) * 100)) if total_tests() else 0

def sha256_payload(payload: Dict[str, Any]) -> str:
    """Canonical CARE payload hash.

    This hash is for the review/snapshot payload only. It intentionally
    excludes fields that merely describe hashes, PDF rendering, or export
    wrappers. A downloaded PDF/JSON file may have a different file hash.
    """
    clean = dict(payload)
    for volatile_key in [
        "report_sha256",
        "export_sha256",
        "hash_clarity",
        "pdf_payload_sha256",
        "json_export_sha256",
        "download_file_sha256",
    ]:
        clean.pop(volatile_key, None)
    return hashlib.sha256(json.dumps(clean, sort_keys=True, ensure_ascii=False, indent=2).encode("utf-8")).hexdigest()


def finalize_report_hash(report: Dict[str, Any]) -> Dict[str, Any]:
    """Finalize a report after all semantic/boundary fields have been added.

    v12.0.2 safety fix:
    Some newer learning/review pages pass smaller payload dictionaries into shared
    PDF/JSON export helpers. Every export payload is now normalized here so
    runtime_id and boundary fields always exist before download keys are built.
    This changes export robustness only. It does not create authority, bind,
    execution, permission or real-world consequence.
    """
    if not isinstance(report, dict):
        report = {}

    report.setdefault("runtime_id", rid())
    report.setdefault("timestamp", now_iso())
    report.setdefault("platform", PLATFORM_NAME)
    report.setdefault("baseline", BASELINE)
    report.setdefault("vNEXT859_status", VNEXT859_STATUS)
    report.setdefault("core_rule", CORE_RULE)
    report.setdefault("unknown_rule", UNKNOWN_RULE)
    report.setdefault("human_rule", HUMAN_RULE)
    report.setdefault("authority_granted", False)
    report.setdefault("bind_granted", False)
    report.setdefault("execution_granted", False)
    report.setdefault("permission_granted", False)
    report.setdefault("human_consequence_allowed", False)
    report.setdefault("non_authority_guard", NON_AUTHORITY_GUARD)

    for volatile_key in ["report_sha256", "hash_clarity", "pdf_payload_sha256", "json_export_sha256", "download_file_sha256"]:
        report.pop(volatile_key, None)
    snapshot_hash = sha256_payload(report)
    report["report_sha256"] = snapshot_hash
    report["hash_clarity"] = {
        "care_snapshot_sha256": snapshot_hash,
        "meaning": "Canonical CARE review snapshot hash. This is not authority, bind, execution, permission or consequence.",
        "pdf_file_sha256": "Calculate after download with a file-hash tool such as Get-FileHash. A PDF cannot safely self-declare its own final file hash.",
        "json_file_sha256": "Calculate after download if exact transport/file integrity is required. JSON file hash may differ from CARE snapshot hash because the file includes hash labels.",
        "boundary": "Hash clarity != authority",
    }
    return report


def report_hash_rows(report: Dict[str, Any]) -> List[Dict[str, str]]:
    snapshot = report.get("report_sha256", sha256_payload(report))
    return [
        {
            "Hash item": "CARE snapshot SHA256",
            "Value": snapshot,
            "Meaning": "Canonical review payload; excludes rendering/download wrapper fields; not authority.",
        },
        {
            "Hash item": "PDF payload SHA256",
            "Value": sha256_payload(report),
            "Meaning": "Payload embedded in the PDF. The downloaded PDF file hash must be checked after download.",
        },
        {
            "Hash item": "Downloaded PDF file SHA256",
            "Value": "Check after download",
            "Meaning": "Use Get-FileHash or another file-hash tool. File hash verifies file integrity, not admissibility.",
        },
        {
            "Hash item": "Downloaded JSON file SHA256",
            "Value": "Check after download",
            "Meaning": "JSON file hash verifies export integrity. It does not create authority or bind.",
        },
    ]

def norm(value: str) -> str:
    return str(value).strip().lower()

def evaluate_care(proof: str, authority: str, current: str, custody: str, freshness: str) -> Tuple[str, str]:
    p, a, c, u, f = map(norm, [proof, authority, current, custody, freshness])
    if p in ["missing", "invalid", "false"]:
        return "FAIL", "Missing or invalid proof -> no bind -> no effect"
    if a in ["missing", "invalid", "false"]:
        return "FAIL", "Missing or invalid authority -> no bind -> no effect"
    if p in ["unknown", "indeterminate", "not verified"]:
        return "HOLD", "Proof unknown / indeterminate -> UNKNOWN -> HOLD"
    if a in ["unknown", "indeterminate", "not verified"]:
        return "HOLD", "Authority unknown / indeterminate -> UNKNOWN -> HOLD"
    if c in ["missing", "unknown", "not verified", "false"]:
        return "HOLD", "Current state not verified -> UNKNOWN -> HOLD"
    if u in ["missing", "unknown", "not verified", "false"]:
        return "HOLD", "Custody not verified -> UNKNOWN -> HOLD"
    if f in ["stale", "unknown", "not verified", "false"]:
        return "HOLD", "Evidence freshness not verified -> UNKNOWN -> HOLD"
    return "PASS", "Observed evidence set complete; PASS remains observer-only and grants no authority"

def evaluate_extended_case(core_decision: str, owner: str, human_path: str, policy_runtime: str, representation_reality: str) -> Tuple[str, str]:
    fields = [norm(owner), norm(human_path), norm(policy_runtime), norm(representation_reality)]
    if core_decision == "FAIL":
        return "FAIL", "Core authority/proof condition failed -> no governed consequence."
    if "no" in fields or "invalid" in fields or "broken" in fields:
        return "FAIL", "Extended case review failed -> no governed consequence."
    if core_decision == "HOLD" or "unknown" in fields or "not verified" in fields:
        return "HOLD", "Extended case review has unresolved conditions -> UNKNOWN -> HOLD."
    return "PASS", "All displayed review conditions appear complete. PASS remains observer-only and grants no authority."

def build_report(case: str, proof: str, authority: str, current: str, custody: str, freshness: str) -> Dict[str, Any]:
    decision_value, result = evaluate_care(proof, authority, current, custody, freshness)
    report = {
        "runtime_id": rid(),
        "timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "scope": HARNESS_SCOPE,
        "core_rule": CORE_RULE,
        "unknown_rule": UNKNOWN_RULE,
        "human_rule": HUMAN_RULE,
        "vNEXT859_status": VNEXT859_STATUS,
        "language": current_lang(),
        "case_name": case,
        "runtime_evidence": {
            "proof_status": proof,
            "authority_status": authority,
            "current_state_status": current,
            "custody_status": custody,
            "evidence_freshness": freshness,
        },
        "decision": decision_value,
        "result": result,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "consequence_allowed": False,
        "continuation_allowed": False,
        "non_authority_guard": NON_AUTHORITY_GUARD,
    }
    return finalize_report_hash(report)

def build_case_report(case_data: Dict[str, Any]) -> Dict[str, Any]:
    core_decision, core_result = evaluate_care(
        case_data["proof_status"],
        case_data["authority_status"],
        case_data["current_state_status"],
        case_data["custody_status"],
        case_data["evidence_freshness"],
    )
    final_decision, final_result = evaluate_extended_case(
        core_decision,
        case_data["authority_owner_status"],
        case_data["human_challenge_path"],
        case_data["policy_runtime_status"],
        case_data["representation_reality_status"],
    )
    report = {
        "runtime_id": rid(),
        "timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "case_version": CASE_VERSION,
        "scope": HARNESS_SCOPE,
        "core_rule": CORE_RULE,
        "unknown_rule": UNKNOWN_RULE,
        "human_rule": HUMAN_RULE,
        "vNEXT859_status": VNEXT859_STATUS,
        "language": current_lang(),
        "case": case_data,
        "core_decision": core_decision,
        "core_result": core_result,
        "decision": final_decision,
        "result": final_result,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "consequence_allowed": False,
        "human_consequence_allowed": False,
        "non_authority_guard": NON_AUTHORITY_GUARD,
    }
    return finalize_report_hash(report)

def build_export() -> Dict[str, Any]:
    payload = {
        "export_timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "core_rule": CORE_RULE,
        "unknown_rule": UNKNOWN_RULE,
        "human_rule": HUMAN_RULE,
        "vNEXT859_status": VNEXT859_STATUS,
        "language": current_lang(),
        "founder": FOUNDER,
        "founder_mission": t("founder_line"),
        "totals": {
            "cycles": len(ALL_CYCLES),
            "tests": total_tests(),
            "pass": total_pass(),
            "fail": total_fail(),
            "health_score": health(),
            "authority_granted": False,
        },
        "authority_map": AUTHORITY_MAP_ITEMS,
        "cycles": ALL_CYCLES,
        "audit_log": st.session_state.audit_log,
        "last_report": st.session_state.last_report,
        "last_case_report": st.session_state.last_case_report,
        "wizard_report": st.session_state.get("wizard_report"),
        "case_library": st.session_state.get("case_library", []),
        "team": {
            "founder": FOUNDER,
            "review_and_stakeholder_support": STAKEHOLDER_SUPPORT,
            "community_contributors": COMMUNITY_CONTRIBUTORS,
        },
        "non_authority_guard": NON_AUTHORITY_GUARD,
    }
    payload["export_sha256"] = sha256_payload(payload)
    return payload

