def escape(value: Any) -> str:
    return str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def hero(title: str, subtitle: str, eyebrow: str) -> None:
    st.markdown(f"""
<div class="care-hero">
  <div class="care-eyebrow">{escape(ui_text(eyebrow))}</div>
  <div class="care-title">{escape(ui_text(title))}</div>
  <div class="care-subtitle">{escape(ui_text(subtitle))}</div>
  <div class="care-pill-row">
    <div class="care-pill">{escape(ui_text('Baseline: vNEXT858'))}</div>
    <div class="care-pill">{escape(ui_text('vNEXT859: NOT CREATED / HOLD'))}</div>
    <div class="care-pill">{escape(ui_text('Observer-only'))}</div>
    <div class="care-pill">{escape(ui_text('No bind · No execution · No effect'))}</div>
  </div>
</div>
""", unsafe_allow_html=True)

def render_hero(page_key: str) -> None:
    title, subtitle, eyebrow = hero_text(page_key)
    hero(title, subtitle, eyebrow)

