def dark_table(rows: List[Dict[str, Any]]) -> None:
    if not rows:
        st.info(ui_text("No rows available."))
        return
    headers = list(rows[0].keys())
    head = "".join(f"<th>{escape(display_value(h))}</th>" for h in headers)
    body_parts = []
    for row in rows:
        cells = []
        for h in headers:
            cells.append(f"<td>{maybe_badge(h, row.get(h, ''))}</td>")
        body_parts.append("<tr>" + "".join(cells) + "</tr>")
    body = "".join(body_parts)
    st.markdown(f"<div class='dark-table-wrap'><table class='dark-care-table'><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>", unsafe_allow_html=True)

