# ============================================================
# PDF report engine
# ============================================================

def pdf_text(value: Any) -> str:
    return str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def slug(value: str) -> str:
    keep = []
    for char in value:
        if char.isalnum():
            keep.append(char)
        elif char in [" ", "-", "_"]:
            keep.append("_")
    out = "".join(keep).strip("_")
    while "__" in out:
        out = out.replace("__", "_")
    return out[:70] or "care_report"

def flatten_rows(rows: List[Dict[str, Any]]) -> List[List[str]]:
    if not rows:
        return []
    headers = list(rows[0].keys())
    table_rows = [headers]
    for row in rows:
        table_rows.append([str(row.get(header, "")) for header in headers])
    return table_rows

def make_pdf_bytes(
    title: str,
    subtitle: str,
    sections: List[Dict[str, Any]],
    payload: Optional[Dict[str, Any]] = None,
    landscape_mode: bool = False,
) -> bytes:
    if not PDF_AVAILABLE:
        raise RuntimeError("ReportLab is not installed. Run: py -m pip install reportlab")

    buffer = BytesIO()
    page_size = landscape(A4) if landscape_mode else A4
    margin = 1.25 * cm if landscape_mode else 1.55 * cm
    doc = SimpleDocTemplate(
        buffer,
        pagesize=page_size,
        rightMargin=margin,
        leftMargin=margin,
        topMargin=1.20 * cm if landscape_mode else 1.35 * cm,
        bottomMargin=1.20 * cm if landscape_mode else 1.35 * cm,
        title=title,
        author=FOUNDER,
    )
    usable_page_width = page_size[0] - (margin * 2)
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="CareTitle",
        parent=styles["Title"],
        alignment=TA_LEFT,
        textColor=colors.HexColor("#0f172a"),
        fontName="Helvetica-Bold",
        fontSize=22,
        leading=27,
        spaceAfter=10,
    ))
    styles.add(ParagraphStyle(
        name="CareSubTitle",
        parent=styles["BodyText"],
        textColor=colors.HexColor("#334155"),
        fontSize=10.5,
        leading=15,
        spaceAfter=12,
    ))
    styles.add(ParagraphStyle(
        name="CareHeading",
        parent=styles["Heading2"],
        textColor=colors.HexColor("#075985"),
        fontName="Helvetica-Bold",
        fontSize=14,
        leading=18,
        spaceBefore=12,
        spaceAfter=8,
    ))
    styles.add(ParagraphStyle(
        name="CareBody",
        parent=styles["BodyText"],
        textColor=colors.HexColor("#111827"),
        fontSize=9.5,
        leading=13,
        spaceAfter=7,
    ))
    styles.add(ParagraphStyle(
        name="CareSmall",
        parent=styles["BodyText"],
        textColor=colors.HexColor("#475569"),
        fontSize=8,
        leading=10,
    ))
    styles.add(ParagraphStyle(
        name="CareTiny",
        parent=styles["BodyText"],
        textColor=colors.HexColor("#475569"),
        fontSize=6.7,
        leading=8.2,
    ))

    story = []
    generated = now_iso()
    header_rows = [
        ["Platform", PLATFORM_NAME],
        ["Founder of CARE", FOUNDER],
        ["Baseline", BASELINE],
        ["vNEXT859", VNEXT859_STATUS],
        ["Scope", HARNESS_SCOPE],
        ["Generated", generated],
        ["Authority granted", "NO"],
    ]
    if payload is not None:
        header_rows.append(["Review payload SHA256", sha256_payload(payload)])
        header_rows.append(["PDF file SHA256", "Check downloaded PDF file after export"])
    else:
        header_rows.append(["Review payload SHA256", hashlib.sha256((title + subtitle + generated).encode("utf-8")).hexdigest()])
        header_rows.append(["PDF file SHA256", "Check downloaded PDF file after export"])

    story.append(Paragraph(pdf_text(title), styles["CareTitle"]))
    story.append(Paragraph(pdf_text(subtitle), styles["CareSubTitle"]))

    meta_table = Table(header_rows, colWidths=[usable_page_width * 0.25, usable_page_width * 0.75])
    meta_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#fef3c7")),
        ("BACKGROUND", (0, 1), (-1, -1), colors.HexColor("#f8fafc")),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.HexColor("#0f172a")),
        ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
        ("FONTNAME", (1, 0), (1, -1), "Helvetica"),
        ("FONTSIZE", (0, 0), (-1, -1), 7.5),
        ("LEADING", (0, 0), (-1, -1), 9),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#cbd5e1")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    story.append(meta_table)
    story.append(Spacer(1, 0.35 * cm))

    story.append(Paragraph("Core CARE reduction", styles["CareHeading"]))
    story.append(Paragraph(pdf_text(CORE_RULE), styles["CareBody"]))
    story.append(Paragraph(pdf_text(UNKNOWN_RULE), styles["CareBody"]))
    story.append(Paragraph(pdf_text(HUMAN_RULE), styles["CareBody"]))
    story.append(Paragraph("This PDF is observer-only. It preserves review information and does not grant authority, bind, execution, permission, consequence, or continuation.", styles["CareSmall"]))

    for section in sections:
        story.append(Paragraph(pdf_text(section.get("title", "Section")), styles["CareHeading"]))
        body = section.get("body")
        if body:
            for paragraph in str(body).split("\n"):
                if paragraph.strip():
                    story.append(Paragraph(pdf_text(paragraph.strip()), styles["CareBody"]))
        rows = section.get("rows")
        if rows:
            table_data = flatten_rows(rows)
            if table_data:
                col_count = len(table_data[0])
                weights = section.get("col_weights")
                if weights and len(weights) == col_count:
                    total_weight = sum(float(w) for w in weights) or 1.0
                    col_widths = [usable_page_width * (float(w) / total_weight) for w in weights]
                else:
                    col_widths = [usable_page_width / col_count] * col_count
                cell_style = styles["CareTiny"] if section.get("compact_pdf") or (landscape_mode and col_count >= 7) else styles["CareSmall"]
                wrapped = []
                for row in table_data:
                    wrapped.append([Paragraph(pdf_text(cell), cell_style) for cell in row])
                table = Table(wrapped, colWidths=col_widths, repeatRows=1)
                table.setStyle(TableStyle([
                    ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0f172a")),
                    ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                    ("BACKGROUND", (0, 1), (-1, -1), colors.HexColor("#f8fafc")),
                    ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#cbd5e1")),
                    ("VALIGN", (0, 0), (-1, -1), "TOP"),
                    ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                    ("TOPPADDING", (0, 0), (-1, -1), 5),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
                ]))
                story.append(table)
                story.append(Spacer(1, 0.2 * cm))

    if payload is not None:
        story.append(PageBreak())
        story.append(Paragraph("Machine-readable review snapshot", styles["CareHeading"]))
        payload_text = json.dumps(payload, indent=2, ensure_ascii=False)
        for line in payload_text.splitlines()[:120]:
            story.append(Paragraph(pdf_text(line), styles["CareSmall"]))
        if len(payload_text.splitlines()) > 120:
            story.append(Paragraph("Snapshot truncated in PDF view. Full machine-readable data is available in JSON export.", styles["CareSmall"]))

    doc.build(story)
    return buffer.getvalue()

def pdf_download_button(
    label: str,
    title: str,
    subtitle: str,
    sections: List[Dict[str, Any]],
    filename_prefix: str,
    payload: Optional[Dict[str, Any]] = None,
    landscape_mode: bool = False,
) -> None:
    if PDF_AVAILABLE:
        try:
            data = make_pdf_bytes(title, subtitle, sections, payload, landscape_mode=landscape_mode)
            unique = hashlib.sha256((filename_prefix + title + current_lang()).encode("utf-8")).hexdigest()[:10]
            st.download_button(
                ui_text(label),
                data,
                f"{slug(filename_prefix)}_{datetime.now().strftime('%Y-%m-%d_%H%M')}.pdf",
                "application/pdf",
                key=f"pdf_{unique}_{datetime.now().strftime('%H%M%S')}",
            )
        except Exception as exc:
            st.error(f"PDF could not be generated: {exc}")
    else:
        st.warning("PDF export requires ReportLab. Install it with: py -m pip install reportlab")

