ALL_PAGE_KEYS = [page for pages in GROUPS.values() for page in pages]


def normalize_group_key(value: Any) -> str:
    """Return stable internal group key even if Streamlit session_state contains a translated label."""
    raw = str(value or "").strip()
    if raw in GROUPS:
        return raw
    for lang_map in GROUP_LABELS.values():
        for key, label in lang_map.items():
            if raw == label:
                return key
    # Extra forgiveness if a label was stored without exact match
    lowered = raw.lower()
    if "kommando" in lowered or "command" in lowered or "core" in lowered or "kerne" in lowered:
        return "command"
    if "release" in lowered or "launch" in lowered or "lancering" in lowered or "zenodo" in lowered or "github" in lowered or "streamlit" in lowered:
        return "external_review_launch"
    if "review" in lowered or "værkt" in lowered:
        return "review_tools"
    if "evidence" in lowered or "beviser" in lowered or "policy" in lowered:
        return "evidence_policy"
    if "scenario" in lowered or "scenar" in lowered or "cycle" in lowered or "cykl" in lowered:
        return "scenarios_cycles"
    if "report" in lowered or "rapport" in lowered or "project" in lowered or "projekt" in lowered:
        return "reports_project"
    return "command"


def normalize_page_key(value: Any, allowed_pages: Optional[List[str]] = None) -> str:
    """Return stable internal page key even if Streamlit session_state contains a translated page label."""
    raw = str(value or "").strip()
    allowed = allowed_pages or ALL_PAGE_KEYS
    if raw in ALL_PAGE_KEYS:
        return raw if raw in allowed else allowed[0]
    for lang_map in PAGE_LABELS.values():
        for key, label in lang_map.items():
            if raw == label:
                return key if key in allowed else allowed[0]
    return allowed[0]


