def case_summary_rows() -> List[Dict[str, Any]]:
    rows = []
    for report in st.session_state.get("case_library", []):
        case = report.get("case", {})
        rows.append({
            "Runtime ID": report.get("runtime_id", ""),
            "Case": case.get("case_name", report.get("case_name", "")),
            "System": case.get("system_type", ""),
            "Decision": report.get("decision", ""),
            "Authority": "NO",
            "Timestamp": report.get("timestamp", ""),
        })
    return rows

def risk_pressure_rows() -> List[Dict[str, Any]]:
    reports = st.session_state.get("case_library", [])
    dimensions = ["proof_status", "authority_status", "current_state_status", "custody_status", "evidence_freshness", "authority_owner_status", "human_challenge_path", "policy_runtime_status", "representation_reality_status"]
    rows = []
    for dim in dimensions:
        unknown = fail = verified = total = 0
        for report in reports:
            case = report.get("case", {})
            value = norm(case.get(dim, "unknown"))
            total += 1
            if value in ["unknown", "not verified", "indeterminate"]:
                unknown += 1
            elif value in ["no", "missing", "invalid", "false", "broken", "stale"]:
                fail += 1
            else:
                verified += 1
        pressure = "LOW"
        if fail > 0:
            pressure = "FAIL PRESSURE"
        elif unknown > 0:
            pressure = "HOLD PRESSURE"
        rows.append({
            "Dimension": dim.replace("_", " ").title(),
            "Cases": total,
            "Verified": verified,
            "Unknown": unknown,
            "Failed": fail,
            "Pressure": pressure,
        })
    return rows


