def page_cycle_search() -> None:
    render_hero("cycle_search")
    q = care_text_input("Search cycles", "", key="cycle_search_v8")
    categories = ["All"] + sorted({c["category"] for c in ALL_CYCLES})
    category = care_selectbox("Category filter", categories, key="cycle_category_v8")
    rows = []
    for c in ALL_CYCLES:
        haystack = f"{c['cycle']} {c['name']} {c['category']} {c['principle']}".lower()
        if q.strip() and q.lower() not in haystack:
            continue
        if category != "All" and c["category"] != category:
            continue
        rows.append({"Cycle": c["cycle"], "Name": c["name"], "Category": c["category"], "Principle": c["principle"], "Authority": c["authority"], "Status": c["status"]})
    st.caption(f"{len(rows)} matching cycles. Search is visibility only and grants no authority.")
    dark_table(rows)

def page_runtime_statistics() -> None:
    render_hero("runtime_statistics")
    kpis()
    by_cat: Dict[str, Dict[str, int]] = {}
    for c in ALL_CYCLES:
        by_cat.setdefault(c["category"], {"Cycles": 0, "Tests": 0, "PASS": 0, "FAIL": 0})
        by_cat[c["category"]]["Cycles"] += 1
        by_cat[c["category"]]["Tests"] += c["tests"]
        by_cat[c["category"]]["PASS"] += c["pass"]
        by_cat[c["category"]]["FAIL"] += c["fail"]
    st.subheader("Coverage by category")
    dark_table([{"Category": key, **value, "Authority": "NO"} for key, value in by_cat.items()])
    st.subheader("Runtime health")
    st.progress(health() / 100)
