def page_self_check() -> None:
    render_hero("self_check")
    checks = []
    all_pages = [page for pages in GROUPS.values() for page in pages]
    checks.append(("Routes cover all pages", all(p in ROUTES for p in all_pages)))
    checks.append(("Every group has at least one page", all(len(v) > 0 for v in GROUPS.values())))
    checks.append(("Language is stable", current_lang() in LANGS))
    checks.append(("vNEXT859 remains HOLD", VNEXT859_STATUS == "NOT CREATED / HOLD"))
    checks.append(("Founder is Nick Vejle", FOUNDER == "Nick Vejle"))
    checks.append(("Demo Mode route is present", "demo_mode" in ROUTES))
    checks.append(("Demo Mode does not authorize", NON_AUTHORITY_GUARD.get("demo_mode_without_authority") is True))
    checks.append(("PDF engine available", PDF_AVAILABLE))
    checks.append(("Non-authority guards present", all(NON_AUTHORITY_GUARD.values())))
    checks.append(("No execution permission exposed", NON_AUTHORITY_GUARD.get("no_proof_no_bind_no_effect") is True))
    rows = [{"Check": name, "Status": "PASS" if ok else "HOLD", "Authority": "NO"} for name, ok in checks]
    dark_table(rows)
    passed = sum(1 for _, ok in checks if ok)
    st.progress(passed / len(checks))
    if passed == len(checks):
        st.success(ui_text("Self-check passed. This does not grant authority."))
    else:
        st.warning(ui_text("Self-check found HOLD items. HOLD prevents authority promotion."))

    report = {
        "platform": PLATFORM_NAME,
        "timestamp": now_iso(),
        "checks": rows,
        "authority_granted": "NO",
        "vNEXT859": VNEXT859_STATUS,
    }
    report["sha256"] = sha256_payload(report)
    st.session_state.self_check_history.append(report)
    st.download_button(
        ui_text("Download self-check JSON"),
        json.dumps(report, indent=2, ensure_ascii=False),
        "CARE_v11_0_5_self_check.json",
        "application/json",
    )
    pdf_download_button(
        ui_text("Download self-check PDF"),
        f"{PLATFORM_NAME} · Runtime Self-Check",
        "Self-check is a review artifact only.",
        [{"title": "Self-check", "body": "Self-check does not grant authority.", "rows": rows}],
        "CARE_v11_0_5_self_check",
        payload=report,
    )



