def visual_bar(label: str, value: int, note: str = "", tone: str = "blue") -> None:
    value = max(0, min(100, int(value)))
    color_map = {"green": "#22c55e", "amber": "#f59e0b", "red": "#ef4444", "blue": "#38bdf8", "purple": "#a78bfa"}
    color = color_map.get(tone, "#38bdf8")
    st.markdown(f"""
<div class="care-panel" style="margin:10px 0;padding:15px 17px;">
  <div style="display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:.45rem;">
    <div style="font-weight:950;color:#f8fafc;">{escape(ui_text(label))}</div>
    <div style="font-weight:950;color:{color};">{value}%</div>
  </div>
  <div style="height:12px;border-radius:999px;background:rgba(15,23,42,.95);border:1px solid rgba(148,163,184,.18);overflow:hidden;">
    <div style="width:{value}%;height:100%;background:{color};border-radius:999px;"></div>
  </div>
  <div class="care-small" style="margin-top:.55rem;">{escape(ui_text(note))}</div>
</div>
""", unsafe_allow_html=True)

def visual_path(steps: List[Dict[str, str]]) -> None:
    html_parts = []
    for step in steps:
        state = step.get("State", "Unknown")
        lower = state.lower()
        cls = "boundary" if lower in ["present", "available", "valid", "verified"] else ("fail" if lower in ["invalid", "blocked", "fail"] else "warning")
        html_parts.append(f"""
<div class="node {cls}">
  <div class="label">{escape(ui_text(step.get("Step", "")))}</div>
  <div class="value">{escape(ui_text(state))}</div>
  <div class="note">{escape(ui_text(step.get("Reduction", "")))}</div>
</div>
""")
    st.markdown("<div class='flow-wrap'>" + "".join(html_parts) + "</div>", unsafe_allow_html=True)

def visual_governance_pdf(page_key: str, title: str, subtitle: str, rows: List[Dict[str, Any]], filename: str) -> None:
    payload = finalize_report_hash({
        "runtime_id": rid(),
        "timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "vNEXT859_status": VNEXT859_STATUS,
        "page_key": page_key,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "human_consequence_allowed": False,
        "rows": rows,
        "non_authority_guard": NON_AUTHORITY_GUARD,
    })

    sections = [
        {
            "title": "Visual governance boundary",
            "body": "This page is observer-only. Visuals explain conditions; they do not create authority, bind, execution, permission or consequence.",
            "rows": [{"Authority": "NO", "Bind": "NO", "Execution": "NO", "Human consequence": "NO"}],
        },
        {
            "title": page_label(page_key),
            "body": subtitle,
            "rows": rows,
        },
    ]

    if page_key == "cycle03_pressure":
        sections.insert(1, {
            "title": "James pressure question",
            "body": "Does UNKNOWN continue to collapse into HOLD when the system is under pressure to continue?",
            "rows": [
                {
                    "Pressure surface": "Ambiguity, incomplete state, conflicting evidence, operational urgency, adoption pressure, dashboard pressure, report pressure, authority inference",
                    "CARE response": "UNKNOWN -> HOLD",
                    "Authority": "NO",
                }
            ],
        })

    sections.extend([
        {
            "title": "Core reduction",
            "body": "Rendered as separate rules to avoid PDF line-break artifacts.",
            "rows": [
                {"Rule": CORE_RULE},
                {"Rule": UNKNOWN_RULE},
                {"Rule": HUMAN_RULE},
            ],
        },
        {
            "title": "Release lock",
            "body": "Polish does not change CARE authority semantics.",
            "rows": [{"vNEXT858": "Baseline", "vNEXT859": "NOT CREATED / HOLD"}],
        },
    ])

    pdf_download_button(f"{t('download_pdf')} · {page_label(page_key)}", f"{PLATFORM_NAME} · {title}", subtitle, sections, filename, payload=payload, landscape_mode=True)
    st.download_button(
        f"{t('download_json')} · {page_label(page_key)}",
        json.dumps(payload, indent=2, ensure_ascii=False).encode("utf-8"),
        f"{slug(filename)}_{datetime.now().strftime('%Y-%m-%d_%H%M')}.json",
        "application/json",
        key=f"json_{page_key}_{payload.get('runtime_id', rid())}",
    )


