def page_challenge_simulator() -> None:
    render_hero("challenge_simulator")
    proof = st.checkbox(ui_text("Proof available"), value=True, key="sim_proof_v103")
    authority = st.checkbox(ui_text("Authority valid"), value=False, key="sim_authority_v103")
    human = st.checkbox(ui_text("Human challenge path verified"), value=False, key="sim_human_v103")
    pressure = st.slider(ui_text("Continuation pressure"), 0, 100, 80, key="sim_pressure_v103")
    if not proof:
        decision = "HOLD"
        why = "Proof missing/unknown -> UNKNOWN -> HOLD"
    elif not authority:
        decision = "HOLD"
        why = "Authority unresolved under pressure -> HOLD"
    elif not human:
        decision = "HOLD"
        why = "Human challenge path unresolved -> HOLD"
    else:
        decision = "PASS"
        why = "Demo PASS remains observer-only and does not grant bind"
    c1, c2, c3 = st.columns(3)
    with c1: card("Decision", decision, why)
    with c2: card("Continuation pressure", f"{pressure}%", "Pressure does not authorize continuation")
    with c3: card("Authority", "NO", "Simulator cannot grant authority")
    rows = [{"Proof": "present" if proof else "unknown", "Authority": "valid" if authority else "unknown", "Human challenge": "verified" if human else "unknown", "Pressure": f"{pressure}%", "Decision": decision, "Boundary": "Simulation != authority"}]
    dark_table(rows)
