def care_guard_review(request: Dict[str, Any]) -> Dict[str, Any]:
    proof = request.get("proof_status", "unknown")
    authority = request.get("authority_status", "unknown")
    current = request.get("current_state_status", "unknown")
    custody = request.get("custody_status", "unknown")
    freshness = request.get("evidence_freshness", "unknown")
    core_decision, core_reason = evaluate_care(proof, authority, current, custody, freshness)
    human_path = norm(request.get("human_challenge_path", "unknown"))
    policy_runtime = norm(request.get("policy_runtime_status", "unknown"))
    sandbox_only = bool(request.get("sandbox_only", True))

    decision_value = core_decision
    reasons = [core_reason]
    if decision_value == "PASS" and human_path in ["unknown", "missing", "no", "not verified"]:
        decision_value = "HOLD"
        reasons.append("Human challenge path unresolved -> UNKNOWN -> HOLD")
    if decision_value == "PASS" and policy_runtime in ["unknown", "missing", "no", "not verified", "broken"]:
        decision_value = "HOLD"
        reasons.append("Policy-to-runtime condition unresolved -> UNKNOWN -> HOLD")
    if not sandbox_only:
        decision_value = "HOLD"
        reasons.append("Live execution requested in demo sandbox -> HOLD")

    report = {
        "runtime_id": rid(),
        "timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "vNEXT859_status": VNEXT859_STATUS,
        "adapter": "CARE Guard Adapter v10.5",
        "request": request,
        "decision": decision_value,
        "reason": " | ".join(reasons),
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "consequence_allowed": False,
        "human_consequence_allowed": False,
        "effect_capable_path_allowed": False,
        "sandbox_only": True,
        "boundary": {
            "integration": "Integration != Authority",
            "api_call": "API call != Bind",
            "tool_access": "Tool access != Permission",
            "sandbox": "Sandbox != Execution",
            "unknown": "UNKNOWN -> HOLD",
        },
        "non_authority_guard": NON_AUTHORITY_GUARD,
    }
    return finalize_report_hash(report)

def integration_pdf(page_key: str, title: str, subtitle: str, rows: List[Dict[str, Any]], filename: str, payload: Optional[Dict[str, Any]] = None) -> None:
    payload = finalize_report_hash(payload or {
        "runtime_id": rid(),
        "timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "vNEXT859_status": VNEXT859_STATUS,
        "page_key": page_key,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "human_consequence_allowed": False,
        "rows": rows,
        "non_authority_guard": NON_AUTHORITY_GUARD,
    })
    sections = [
        {
            "title": "Integration sandbox boundary",
            "body": "This page is local simulation only. Integration, API calls, policy-as-code, tool gates, ledgers and deployment checks do not create authority, bind, execution, permission or consequence.",
            "rows": [{"Integration": "NO AUTHORITY", "API call": "NO BIND", "Tool access": "NO PERMISSION", "Sandbox": "NO EXECUTION"}],
        },
        {"title": title, "body": subtitle, "rows": rows},
        {
            "title": "Core reduction",
            "body": "The integration sandbox preserves the existing CARE baseline.",
            "rows": [{"Rule": CORE_RULE}, {"Rule": UNKNOWN_RULE}, {"Rule": HUMAN_RULE}],
        },
        {"title": "Release lock", "body": "v10.5 adds integration surfaces without expanding authority posture.", "rows": [{"vNEXT858": "Baseline", "vNEXT859": "NOT CREATED / HOLD"}]},
    ]
    pdf_download_button(f"{t('download_pdf')} · {page_label(page_key)}", f"{PLATFORM_NAME} · {title}", subtitle, sections, filename, payload=payload, landscape_mode=True)
    st.download_button(
        f"{t('download_json')} · {page_label(page_key)}",
        json.dumps(payload, indent=2, ensure_ascii=False).encode("utf-8"),
        f"{slug(filename)}_{datetime.now().strftime('%Y-%m-%d_%H%M')}.json",
        "application/json",
        key=f"json_{page_key}_{payload.get('runtime_id', rid())}",
    )

def page_care_guard_adapter() -> None:
    render_hero("care_guard_adapter")
    st.info(ui_text("Local simulator only. The adapter can return PASS/HOLD/FAIL, but it never grants authority, bind, execution or real-world consequence."))
    example = json.dumps(CARE_GUARD_EXAMPLE, indent=2, ensure_ascii=False)
    raw = st.text_area(ui_text("Adapter input JSON"), value=example, height=330, key="care_guard_adapter_input_v104")
    if st.button(ui_text("Run CARE Guard Adapter review"), key="run_care_guard_adapter_v104", type="primary"):
        try:
            request = json.loads(raw)
            report = care_guard_review(request)
            st.session_state.adapter_last_response = report
            st.session_state.integration_ledger.append(report)
            st.session_state.last_case_report = report
            st.session_state.audit_log.append(report)
            st.success(ui_text(f"Adapter review completed: {report['decision']} — no authority granted."))
            st.json(report)
        except Exception as exc:
            st.error(f"Invalid adapter JSON: {exc}")
    rows = [
        {"Field": "Adapter", "Value": "CARE Guard Adapter v10.5", "Boundary": "Adapter != Authority"},
        {"Field": "API call", "Value": "Local simulation", "Boundary": "API call != Bind"},
        {"Field": "Execution", "Value": "NO", "Boundary": "Sandbox != Execution"},
        {"Field": "Default unknown", "Value": "HOLD", "Boundary": "UNKNOWN -> HOLD"},
    ]
    dark_table(rows)
    payload = st.session_state.get("adapter_last_response") or care_guard_review(CARE_GUARD_EXAMPLE)
    integration_pdf("care_guard_adapter", "CARE Guard Adapter", "Local adapter review simulator. It returns review data without authority.", rows, "CARE_v11_0_5_guard_adapter", payload=payload)

