def validate_integration_request(request: Dict[str, Any]) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    required = ["system", "proposed_action", "potential_consequence", "proof_status", "authority_status"]
    rows: List[Dict[str, Any]] = []
    for key in required:
        present = key in request and str(request.get(key, "")).strip() != ""
        rows.append({"Field": key, "Status": "PASS" if present else "HOLD", "Meaning": "Present" if present else "Missing -> UNKNOWN/HOLD", "Authority": "NO"})
    report = care_guard_review({**CARE_GUARD_EXAMPLE, **request})
    return rows, report

def external_pdf(page_key: str, title: str, subtitle: str, rows: List[Dict[str, Any]], filename: str, payload: Optional[Dict[str, Any]] = None) -> None:
    integration_pdf(page_key, title, subtitle, rows, filename, payload=payload)


# ============================================================
# v10.6 helper fix — JSON download + text hash
# Observer-only utility helpers. Downloads and hashes do NOT create
# authority, bind, execution, permission, consequence, or continuation.
# ============================================================

def sha256_text(value: Any) -> str:
    """Return SHA256 for stable text or JSON-like payloads.

    Hashing verifies integrity only. It does not grant authority, bind,
    execution, permission, consequence, or continuation.
    """
    if not isinstance(value, str):
        value = json.dumps(
            value,
            sort_keys=True,
            ensure_ascii=False,
            separators=(",", ":"),
        )
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def json_download_button(label: str, payload: Any, filename_prefix: str) -> None:
    """Stable JSON download helper used by v10.5 integration pages.

    JSON export is an observer-only review artifact. It does not grant
    authority, bind, execution, permission, consequence, or continuation.
    """
    try:
        data = json.dumps(payload, indent=2, ensure_ascii=False)
    except TypeError:
        data = json.dumps(str(payload), indent=2, ensure_ascii=False)

    unique = hashlib.sha256(
        (filename_prefix + label + data[:2048] + current_lang()).encode("utf-8")
    ).hexdigest()[:10]

    st.download_button(
        label,
        data,
        f"{slug(filename_prefix)}_{datetime.now().strftime('%Y-%m-%d_%H%M')}.json",
        "application/json",
        key=f"json_{unique}_{datetime.now().strftime('%H%M%S')}",
    )

