def pilot_readiness_score() -> Tuple[int, int]:
    total = sum(int(r["Weight"]) for r in PILOT_READINESS_COMPONENTS)
    score = sum(int(r["Score"]) for r in PILOT_READINESS_COMPONENTS)
    return score, total

def build_pilot_case(system: str) -> Dict[str, Any]:
    template = PILOT_CASE_TEMPLATES.get(system, PILOT_CASE_TEMPLATES["Municipality AI"])
    request = {
        "request_id": "pilot_" + slug(system),
        "system": system,
        "proposed_action": template["proposed_action"],
        "potential_consequence": template["potential_consequence"],
        "proof_status": "unknown",
        "authority_status": "unknown",
        "current_state_status": "unknown",
        "custody_status": "unknown",
        "evidence_freshness": "unknown",
        "human_challenge_path": "unknown",
        "sandbox_only": True,
        "external_execution_requested": False,
        "primary_gap": template["primary_gap"],
    }
    report = care_guard_review(request)
    report["pilot_case"] = request
    report["primary_gap"] = template["primary_gap"]
    report["v10_6_boundary"] = "Pilot case builder != real-world decision"
    return finalize_report_hash(report)

def verification_pack_payload() -> Dict[str, Any]:
    score, total = pilot_readiness_score()
    sample_case = build_pilot_case("Municipality AI")
    payload = {
        "runtime_id": rid(),
        "timestamp": now_iso(),
        "platform": PLATFORM_NAME,
        "baseline": BASELINE,
        "vNEXT859_status": VNEXT859_STATUS,
        "pilot_readiness_score": f"{score}/{total}",
        "pilot_readiness_percent": round((score / total) * 100, 1) if total else 0,
        "sample_case": sample_case,
        "contract_tests": CONTRACT_TEST_ROWS,
        "partner_risks": PARTNER_RISK_ROWS,
        "deployment_readiness": DEPLOYMENT_READINESS_AUDIT_ROWS,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "human_consequence_allowed": False,
        "non_authority_guard": NON_AUTHORITY_GUARD,
    }
    return finalize_report_hash(payload)

