# ============================================================
# CARE Runtime v11.3 Human Consequence Demo pages
# Scenario demos help people understand CARE without turning the
# runtime into a municipality, hospital, insurance, banking,
# medical, legal or financial decision system.
# ============================================================

def v113_status_badge(value: str) -> str:
    value = str(value or "unknown")
    if value in {"present", "valid", "verified", "fresh", "yes"}:
        return "OK"
    if value in {"invalid", "no"}:
        return "FAIL"
    return "HOLD"


def v113_evaluate_case(proof: str, authority: str, current_state: str, custody: str, human_consequence: str = "yes") -> Tuple[str, str, List[Dict[str, Any]]]:
    checks = [
        {"Checkpoint": "Proof", "Value": proof, "CARE reading": "Proof must be present before consequence can be reviewed."},
        {"Checkpoint": "Authority", "Value": authority, "CARE reading": "Authority must be valid at the consequence boundary."},
        {"Checkpoint": "Current state", "Value": current_state, "CARE reading": "The actual present state must be verified."},
        {"Checkpoint": "Custody", "Value": custody, "CARE reading": "Evidence custody must remain reviewable."},
        {"Checkpoint": "Human consequence", "Value": human_consequence, "CARE reading": HUMAN_RULE},
    ]
    for row in checks:
        row["Local status"] = v113_status_badge(row["Value"])

    if authority == "invalid":
        decision = "FAIL"
        reason = "Invalid authority at the boundary -> no valid bind authority -> no governed human consequence."
    elif proof != "present" or authority != "valid" or current_state != "verified" or custody != "verified":
        decision = "HOLD"
        reason = "One or more required conditions are missing or unknown -> UNKNOWN -> HOLD."
    elif human_consequence in {"yes", "unknown"}:
        decision = "PASS"
        reason = "Review conditions are present. PASS remains observer-only and does not execute or authorize consequence."
    else:
        decision = "PASS"
        reason = "No human consequence selected. PASS remains review-only and non-authoritative."
    return decision, reason, checks


def v113_render_result(decision: str, reason: str) -> None:
    c1, c2, c3, c4 = st.columns(4)
    with c1: card("Result", decision, "Review output only")
    with c2: card("Authority granted", "0", "No bind created")
    with c3: card("Execution", "NO", "No real-world action")
    with c4: card("Human consequence", "NO", HUMAN_RULE)
    panel(f"CARE result: {decision}", reason + " This page is a scenario demo only; it cannot replace legal, medical, financial, municipal or human responsibility.")


def v113_payload(page: str, scenario: str, decision: str, rows: List[Dict[str, Any]], reason: str) -> Dict[str, Any]:
    payload = external_review_payload(page, rows)
    payload.update({
        "release": "CARE Runtime v11.3",
        "edition": "Human Consequence Demo Edition",
        "scenario": scenario,
        "decision": decision,
        "reason": reason,
        "authority_granted": 0,
        "bind_granted": 0,
        "execution_granted": 0,
        "human_consequence_allowed": 0,
        "vNEXT859": VNEXT859_STATUS,
    })
    return payload


def page_care_playground() -> None:
    render_hero("care_playground")
    c1, c2 = st.columns(2)
    with c1:
        scenario = st.text_input("Scenario name", "Human consequence review", key="v113_playground_scenario")
        proof = care_selectbox("Proof available?", ["present", "missing", "unknown"], index=2, key="v113_playground_proof")
        authority = care_selectbox("Authority valid?", ["valid", "invalid", "unknown"], index=2, key="v113_playground_authority")
    with c2:
        current_state = care_selectbox("Current state verified?", ["verified", "missing", "unknown"], index=2, key="v113_playground_current")
        custody = care_selectbox("Custody verified?", ["verified", "missing", "unknown"], index=2, key="v113_playground_custody")
        human_consequence = care_selectbox("Human consequence?", ["yes", "no", "unknown"], index=0, key="v113_playground_human")
    decision, reason, rows = v113_evaluate_case(proof, authority, current_state, custody, human_consequence)
    v113_render_result(decision, reason)
    dark_table(rows)
    panel("Playground boundary", "This page makes CARE easier to understand. It does not make CARE a decision-maker. PASS/HOLD/FAIL are review states only.")
    payload = v113_payload("care_playground", scenario, decision, rows, reason)
    external_pdf("care_playground", "CARE Playground", "No bind -> no human consequence.", rows, "CARE_v11_3_care_playground", payload=payload)
    json_download_button("Download Playground JSON", payload, "CARE_v11_3_care_playground")


