# ============================================================
# CARE Runtime v11.4 Agent Firewall Preview pages
# These pages are simulation surfaces only. They do not execute
# emails, records, payments, cases, APIs, databases or tools.
# ============================================================

def v114_status(value: str) -> str:
    value = str(value or "unknown")
    if value in {"present", "valid", "verified", "approved", "sandboxed", "yes", "blocked"}:
        return "OK"
    if value in {"invalid", "real_world", "bypass", "no"}:
        return "FAIL"
    return "HOLD"


def v114_agent_evaluate(proof: str, authority: str, boundary: str, human_review: str, sandbox: str, tool_access: str = "available") -> Tuple[str, str, List[Dict[str, Any]]]:
    rows = [
        {"Checkpoint": "Proof", "Value": proof, "CARE reading": "Proof must be present before action can be reviewed."},
        {"Checkpoint": "Authority", "Value": authority, "CARE reading": "Authority must be valid at the exact proposed effect boundary."},
        {"Checkpoint": "Boundary", "Value": boundary, "CARE reading": "The action boundary must be verified before any bind review."},
        {"Checkpoint": "Human review", "Value": human_review, "CARE reading": "Human presence is not authority unless valid review authority exists."},
        {"Checkpoint": "Tool access", "Value": tool_access, "CARE reading": "Tool access is capability, not authority."},
        {"Checkpoint": "Sandbox mode", "Value": sandbox, "CARE reading": "This demo must remain sandbox-only and non-executing."},
    ]
    for row in rows:
        row["Local status"] = v114_status(row["Value"])

    if authority == "invalid" or boundary == "bypass" or sandbox == "real_world":
        decision = "FAIL"
        reason = "Invalid authority, bypassed boundary or real-world execution request -> no governed tool action. Tool execution remains blocked."
    elif proof != "present" or authority != "valid" or boundary != "verified" or human_review != "approved" or sandbox != "sandboxed":
        decision = "HOLD"
        reason = "One or more action conditions are missing or unknown -> UNKNOWN -> HOLD. No tool execution is allowed."
    else:
        decision = "PASS"
        reason = "Review conditions are present for the mock scenario. PASS remains review-only and still does not execute the tool."
    return decision, reason, rows


def v114_render_agent_result(decision: str, reason: str) -> None:
    c1, c2, c3, c4 = st.columns(4)
    with c1: card("Review result", decision, "Observer-only")
    with c2: card("Tool executed", "NO", "Execution blocked")
    with c3: card("Bind granted", "0", "No authority created")
    with c4: card("Human consequence", "NO", HUMAN_RULE)
    panel(f"Agent firewall result: {decision}", reason + " CARE Runtime does not send emails, delete records, approve payments, close cases, update databases or call APIs.")


def v114_payload(page: str, scenario: str, decision: str, rows: List[Dict[str, Any]], reason: str) -> Dict[str, Any]:
    payload = external_review_payload(page, rows)
    payload.update({
        "release": "CARE Runtime v11.4",
        "edition": "Agent Firewall Preview Edition",
        "scenario": scenario,
        "decision": decision,
        "reason": reason,
        "tool_executed": 0,
        "authority_granted": 0,
        "bind_granted": 0,
        "execution_granted": 0,
        "human_consequence_allowed": 0,
        "vNEXT859": VNEXT859_STATUS,
    })
    return payload


def page_ai_agent_firewall_demo() -> None:
    render_hero("ai_agent_firewall_demo")
    c1, c2 = st.columns(2)
    with c1:
        action = care_selectbox("Proposed agent action", ["Send email", "Delete record", "Approve payment", "Close case", "Update database", "Call external API"], key="v114_agent_action")
        proof = care_selectbox("Proof available?", ["present", "missing", "unknown"], index=2, key="v114_agent_proof")
        authority = care_selectbox("Authority valid?", ["valid", "invalid", "unknown"], index=2, key="v114_agent_authority")
    with c2:
        boundary = care_selectbox("Action boundary verified?", ["verified", "missing", "unknown", "bypass"], index=2, key="v114_agent_boundary")
        human_review = care_selectbox("Human review approved?", ["approved", "missing", "unknown"], index=2, key="v114_agent_human_review")
        sandbox = care_selectbox("Execution mode", ["sandboxed", "real_world", "unknown"], index=0, key="v114_agent_sandbox")
    decision, reason, rows = v114_agent_evaluate(proof, authority, boundary, human_review, sandbox)
    v114_render_agent_result(decision, reason)
    dark_table(rows)
    panel("Agent boundary", "The agent may propose an action. The runtime may inspect the proposal. Neither proposal nor inspection creates permission to execute.")
    payload = v114_payload("ai_agent_firewall_demo", action, decision, rows, reason)
    external_pdf("ai_agent_firewall_demo", "AI Agent Firewall Demo", "Tool access is not authority.", rows, "CARE_v11_4_ai_agent_firewall_demo", payload=payload)
    json_download_button("Download Agent Firewall JSON", payload, "CARE_v11_4_ai_agent_firewall_demo")


def page_tool_call_firewall() -> None:
    render_hero("tool_call_firewall")
    cases = {
        "Delete record — proof missing": ("Delete record", "missing", "valid", "verified", "approved", "sandboxed"),
        "Approve payment — authority invalid": ("Approve payment", "present", "invalid", "verified", "approved", "sandboxed"),
        "Call API — boundary unknown": ("Call external API", "present", "valid", "unknown", "approved", "sandboxed"),
        "Update database — sandbox review complete": ("Update database", "present", "valid", "verified", "approved", "sandboxed"),
        "Send email — real-world execution requested": ("Send email", "present", "valid", "verified", "approved", "real_world"),
    }
    selected = care_selectbox("Mock tool-call scenario", list(cases.keys()), key="v114_tool_case")
    action, proof, authority, boundary, human_review, sandbox = cases[selected]
    decision, reason, rows = v114_agent_evaluate(proof, authority, boundary, human_review, sandbox)
    stages = [
        {"Stage": "1", "Firewall step": "Tool request received", "Reading": action, "Execution": "NO"},
        {"Stage": "2", "Firewall step": "Evidence checked", "Reading": proof, "Execution": "NO"},
        {"Stage": "3", "Firewall step": "Authority checked", "Reading": authority, "Execution": "NO"},
        {"Stage": "4", "Firewall step": "Boundary checked", "Reading": boundary, "Execution": "NO"},
        {"Stage": "5", "Firewall step": "CARE result", "Reading": decision, "Execution": "NO"},
        {"Stage": "6", "Firewall step": "Tool execution", "Reading": "blocked / not performed", "Execution": "NO"},
    ]
    v114_render_agent_result(decision, reason)
    dark_table(stages)
    panel("Tool-call boundary", "A tool call can be visible, logged, requested, reviewed and replayed. None of those states are bind authority or real-world execution permission.")
    payload = v114_payload("tool_call_firewall", selected, decision, stages + rows, reason)
    external_pdf("tool_call_firewall", "Tool Call Firewall", "API access is not bind.", stages, "CARE_v11_4_tool_call_firewall", payload=payload)
    json_download_button("Download Tool Firewall JSON", payload, "CARE_v11_4_tool_call_firewall")


