# ============================================================
# CARE Runtime v11.5 Critical Systems pages
# These pages are simulation surfaces only. They do not operate,
# authorize, stabilize, continue, redirect or execute infrastructure,
# trade, logistics, emergency or public-system actions.
# ============================================================

def v115_status(value: str) -> str:
    value = str(value or "unknown")
    if value in {"present", "valid", "verified", "bounded", "reviewed", "low", "contained", "yes"}:
        return "OK"
    if value in {"invalid", "bypass", "divergent", "unbounded", "real_world"}:
        return "FAIL"
    return "HOLD"


def v115_boundary_evaluate(proof: str, authority: str, current_state: str, boundary: str, consequence_scope: str = "human/system") -> Tuple[str, str, List[Dict[str, Any]]]:
    rows = [
        {"Checkpoint": "Proof", "Value": proof, "CARE reading": "Proof must be present before any critical-system consequence can be reviewed."},
        {"Checkpoint": "Authority", "Value": authority, "CARE reading": "Authority must be valid at the exact proposed effect boundary."},
        {"Checkpoint": "Current state", "Value": current_state, "CARE reading": "Current operational reality must be verified, not assumed from history or trust."},
        {"Checkpoint": "Boundary", "Value": boundary, "CARE reading": "The consequence boundary must be bounded and reviewable before bind review."},
        {"Checkpoint": "Consequence scope", "Value": consequence_scope, "CARE reading": "Scope awareness is not permission; human/system consequence remains non-executed."},
    ]
    for row in rows:
        row["Local status"] = v115_status(row["Value"])

    if authority == "invalid" or current_state == "divergent" or boundary in {"bypass", "unbounded"}:
        decision = "FAIL"
        reason = "Invalid authority, divergent state or unbounded/bypassed boundary -> no governed critical-system consequence. No replacement action is executed."
    elif proof != "present" or authority != "valid" or current_state != "verified" or boundary != "bounded":
        decision = "HOLD"
        reason = "One or more critical boundary conditions are missing or unknown -> UNKNOWN -> HOLD. Continuity pressure does not promote the result."
    else:
        decision = "PASS"
        reason = "Boundary review conditions are present for the mock scenario. PASS remains review-only and does not authorize, continue or execute consequence."
    return decision, reason, rows


def v115_render_result(decision: str, reason: str, signal_label: str = "Critical signal") -> None:
    c1, c2, c3, c4 = st.columns(4)
    with c1: card("Review result", decision, "Observer-only")
    with c2: card("Authority granted", "0", "No authority created")
    with c3: card("Bind granted", "0", "No bind created")
    with c4: card("Execution", "NO", "No real-world action")
    panel(f"{signal_label}: {decision}", reason + " CARE Runtime does not operate critical infrastructure, route logistics, authorize trade, trigger emergency actions or create human/system consequence.")


def v115_payload(page: str, scenario: str, decision: str, rows: List[Dict[str, Any]], reason: str) -> Dict[str, Any]:
    payload = external_review_payload(page, rows)
    payload.update({
        "release": "CARE Runtime v11.5",
        "edition": "Critical Systems Edition",
        "scenario": scenario,
        "decision": decision,
        "reason": reason,
        "authority_granted": 0,
        "bind_granted": 0,
        "execution_granted": 0,
        "critical_system_action_executed": 0,
        "human_consequence_allowed": 0,
        "vNEXT859": VNEXT859_STATUS,
    })
    return payload


