    render_hero("critical_infrastructure_demo")
    c1, c2 = st.columns(2)
    with c1:
        sector = care_selectbox("Critical sector", ["Energy grid", "Water system", "Hospital operations", "Transport network", "Communications", "Cyber incident response"], key="v115_ci_sector")
        criticality = st.slider("Criticality", 0, 100, 95, key="v115_ci_criticality")
        uptime = st.slider("Uptime / reliability", 0, 100, 99, key="v115_ci_uptime")
        dependency = st.slider("Public dependency", 0, 100, 92, key="v115_ci_dependency")
    with c2:
        proof = care_selectbox("Proof available?", ["present", "missing", "unknown"], index=2, key="v115_ci_proof")
        authority = care_selectbox("Authority valid?", ["valid", "invalid", "unknown"], index=2, key="v115_ci_authority")
        current_state = care_selectbox("Current state verified?", ["verified", "unknown", "divergent"], index=1, key="v115_ci_state")
        boundary = care_selectbox("Effect boundary", ["bounded", "unknown", "unbounded", "bypass"], index=1, key="v115_ci_boundary")
    decision, reason, rows = v115_boundary_evaluate(proof, authority, current_state, boundary, "critical infrastructure")
    signal_rows = [
        {"Signal": "Critical sector", "Value": sector, "CARE contribution": "Context only — not authority."},
        {"Signal": "Criticality", "Value": criticality, "CARE contribution": "Importance does not reduce proof burden."},
        {"Signal": "Uptime / reliability", "Value": uptime, "CARE contribution": "Reliability is not permission."},
        {"Signal": "Public dependency", "Value": dependency, "CARE contribution": "Dependency is not bind."},
    ]
    v115_render_result(decision, reason, "Critical infrastructure review")
    dark_table(signal_rows + rows)
    panel("Critical systems boundary", "Critical infrastructure may be essential, trusted and reliable. CARE still requires present proof, valid authority, verified current state and a bounded effect surface before any consequence can be reviewed.")
