def page_operational_pressure_lab() -> None:
    render_hero("operational_pressure_lab")
    c1, c2, c3 = st.columns(3)
    with c1:
        urgency = st.slider("Urgency", 0, 100, 90, key="v115_pressure_urgency")
        dependency = st.slider("Dependency", 0, 100, 86, key="v115_pressure_dependency")
