def v117_payload(page: str, rows: List[Dict[str, Any]], title: str) -> Dict[str, Any]:
    payload = external_review_payload(page, rows)
    payload.update({
        "release": "CARE Runtime v11.7",
        "edition": "Why CARE Exists + Journey Edition",
        "title": title,
        "authority_granted": 0,
        "bind_granted": 0,
        "execution_granted": 0,
        "story_authority_created": 0,
        "milestone_authority_created": 0,
        "human_consequence_allowed": 0,
        "vNEXT859": VNEXT859_STATUS,
    })
    return payload


