    dark_table(V120_PRESSURE_ROWS)
    panel("Pressure testing boundary", "The library makes CARE more challengeable. Running tests may reveal pressure, confusion or missing proof; it does not authorize any consequence.")
    st.markdown("### Public compression")
    st.code("Do not trust CARE. Test CARE. Test results do not grant bind.", language="text")
    selected = st.selectbox("Select a pressure test", [r["Pressure test"] for r in V120_PRESSURE_ROWS], key="v120_pressure_select")
    row = next(r for r in V120_PRESSURE_ROWS if r["Pressure test"] == selected)
    if st.button("Run selected pressure test", key="run_v120_pressure_test", type="primary"):
        st.session_state.v120_pressure_result = {"selected": selected, "result": row["CARE result"], "boundary": row["Boundary"], "timestamp": now_iso()}
    if st.session_state.get("v120_pressure_result"):
        st.success("Pressure test completed. Boundary preserved; no authority granted.")
        st.json(st.session_state.v120_pressure_result)
    payload = v120_payload("pressure_test_library", V120_PRESSURE_ROWS, "Pressure Test Library")
    external_pdf("pressure_test_library", "Pressure Test Library", "Do not trust CARE. Test CARE.", V120_PRESSURE_ROWS, "CARE_v12_0_pressure_test_library", payload=payload)
