def language_qa_rows() -> List[Dict[str, Any]]:
    """Static bilingual route/label coverage check.
    This is a review artifact only and cannot create authority, bind, execution, or permission.
    """
    rows: List[Dict[str, Any]] = []
    all_pages = [page for pages in GROUPS.values() for page in pages]
    en_labels = PAGE_LABELS.get("English", {})
    da_labels = PAGE_LABELS.get("Dansk", {})
    for page in all_pages:
        en = en_labels.get(page, "")
        da = da_labels.get(page, "")
        rows.append({
            "Route": page,
            "English label": en or "Missing",
            "Danish label": da or "Missing",
            "Covered": "PASS" if en and da else "HOLD",
            "Authority": "NO",
        })
    return rows

def language_qa_summary() -> Dict[str, Any]:
    rows = language_qa_rows()
    total = len(rows)
    covered = sum(1 for r in rows if r["Covered"] == "PASS")
    missing = total - covered
    return {
        "total_routes": total,
        "covered_routes": covered,
        "missing_routes": missing,
        "coverage_percent": round((covered / total) * 100, 2) if total else 0,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "rule": "Language switch != Authority",
    }

def page_language_qa_center() -> None:
    render_hero("language_qa_center")
    st.info(ui_text("Language switching is accessibility only. It does not create authority."))

    summary = language_qa_summary()
