def _safe_source_for_route(page_key: str) -> str:
    fn = ROUTES.get(page_key)
    if not callable(fn):
        return ""
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""

def page_coverage_rows() -> List[Dict[str, Any]]:
    """Static page coverage audit.

    It checks whether every grouped page has route registration, bilingual labels,
    content signals, and export/download surface signals. This does not execute
    page functions and cannot create authority, bind, execution, or permission.
    """
    en_labels = PAGE_LABELS.get("English", {})
    da_labels = PAGE_LABELS.get("Dansk", {})
    grouped_pages: List[str] = []
    for pages in GROUPS.values():
        grouped_pages.extend(pages)

    unique_pages = []
    seen = set()
    for p in grouped_pages:
        if p not in seen:
            unique_pages.append(p)
            seen.add(p)

    rows: List[Dict[str, Any]] = []
    content_tokens = ["render_hero(", "st.markdown", "st.info", "st.success", "st.warning", "dark_table(", "card(", "panel(", "probe_core("]
    export_tokens = ["download_button", "pdf_download_button", "external_pdf", "integration_pdf", "st.download_button"]

    for page in unique_pages:
        route_present = page in ROUTES and callable(ROUTES.get(page))
        src = _safe_source_for_route(page)
        en_ok = bool(en_labels.get(page))
        da_ok = bool(da_labels.get(page))
        content_ok = bool(src) and any(tok in src for tok in content_tokens)
        export_ok = bool(src) and any(tok in src for tok in export_tokens)
        status = "PASS" if route_present and en_ok and da_ok and content_ok else "HOLD"
        rows.append({
            "Page": page,
            "Route present": "PASS" if route_present else "HOLD",
            "Callable": "PASS" if route_present else "HOLD",
            "English label present": "PASS" if en_ok else "HOLD",
            "Danish label present": "PASS" if da_ok else "HOLD",
            "Content signal": "PASS" if content_ok else "HOLD",
            "Export signal": "PASS" if export_ok else "HOLD",
            "Source length": len(src),
            "Coverage status": status,
            "Authority": "NO",
        })
    return rows

def runtime_inventory_summary() -> Dict[str, Any]:
    grouped_pages = [page for pages in GROUPS.values() for page in pages]
    unique_pages = list(dict.fromkeys(grouped_pages))
    rows = page_coverage_rows()
    missing_routes = [r["Page"] for r in rows if r["Route present"] != "PASS"]
    missing_en = [r["Page"] for r in rows if r["English label present"] != "PASS"]
    missing_da = [r["Page"] for r in rows if r["Danish label present"] != "PASS"]
    missing_content = [r["Page"] for r in rows if r["Content signal"] != "PASS"]
    pass_count = sum(1 for r in rows if r["Coverage status"] == "PASS")
    hold_count = len(rows) - pass_count
    return {
        "total_groups": len(GROUPS),
        "grouped_page_entries": len(grouped_pages),
        "unique_pages": len(unique_pages),
        "routes_registered": len(ROUTES),
        "missing_routes": len(missing_routes),
        "missing_english_labels": len(missing_en),
        "missing_danish_labels": len(missing_da),
        "missing_content_signals": len(missing_content),
        "coverage_pass": pass_count,
        "coverage_hold": hold_count,
        "non_authority_guards": len(NON_AUTHORITY_GUARD),
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
    }

