def v121_runtime_scenario(proof: bool, authority: bool, current_state: bool, bind: bool, human_surface: bool = True) -> Dict[str, Any]:
    """Resolve runtime-reality demo state."""
    if not proof:
        verdict = "HOLD"
        failed_at = "Proof"
        reason = "Missing proof -> no bind -> no effect"
    elif not authority:
        verdict = "HOLD"
        failed_at = "Authority"
        reason = "Missing authority -> no valid bind"
    elif not current_state:
        verdict = "HOLD"
        failed_at = "Current state"
        reason = "Current state unknown -> UNKNOWN -> HOLD"
    elif not bind:
        verdict = "HOLD"
        failed_at = "Bind"
        reason = "No bind -> no effect-capable path"
    else:
        verdict = "PASS"
        failed_at = "None"
        reason = "All demo conditions present for review only"

    return {
        "proof": proof,
        "authority": authority,
        "current_state": current_state,
        "bind": bind,
        "human_surface": human_surface,
        "verdict": verdict,
        "failed_at": failed_at,
        "reason": reason,
        "consequence_real": verdict == "PASS",
        "human_consequence_allowed": verdict == "PASS" and human_surface,
        "authority_granted": False,
        "execution_granted": False,
        "permission_granted": False,
    }

def v121_boundary_rows(state: Dict[str, Any]) -> List[Dict[str, Any]]:
    path = [
        ("Idea / proposal", True, "Potential only"),
        ("Proof", state["proof"], "No proof -> HOLD"),
        ("Authority", state["authority"], "Trust is not authority"),
        ("Current state", state["current_state"], "UNKNOWN -> HOLD"),
        ("Bind", state["bind"], "No bind -> no effect"),
        ("Consequence", state["verdict"] == "PASS", "Consequence blocked unless valid bind"),
        ("Human consequence", state["human_consequence_allowed"], "No bind -> no human consequence"),
    ]
    return [
        {
            "Step": name,
            "Status": "PASS" if ok else "HOLD",
            "Boundary note": note,
            "Authority": "NO",
        }
        for name, ok, note in path
    ]

def page_runtime_reality_explorer() -> None:
    render_hero("runtime_reality_explorer")
    st.info(ui_text("Potential is not reality. Capability is not consequence."))

    c1, c2, c3, c4 = st.columns(4)
