    for s in v124_authority_inference_catalog():
        result = v124_eval_authority_inference(s)
        rows.append({
            "Legitimacy surface": s["name"],
            "Ecosystem pressure": s["pressure"],
            "Boundary": s["boundary"],
            "Observed verdict": result["observed_verdict"],
            "Authority": "NO",
        })
    return rows

