    chosen = st.selectbox("Richard pressure surface", [s["name"] for s in catalog], key="v124_surface_select")
    surface = next(s for s in catalog if s["name"] == chosen)

    st.markdown("### " + ui_text("Legitimacy surface"))
    st.write(surface["surface"])
    st.markdown("### Boundary")
    st.write(surface["boundary"])

    c1, c2, c3 = st.columns(3)
    with c1:
        current_proof = st.checkbox("Current proof", value=False, key=f"v124_{surface['id']}_proof")
    with c2:
        current_authority = st.checkbox("Current authority", value=False, key=f"v124_{surface['id']}_authority")
    with c3:
        current_bind = st.checkbox("Current bind", value=False, key=f"v124_{surface['id']}_bind")

    result = v124_eval_authority_inference(surface, current_proof, current_authority, current_bind)

    c1, c2, c3 = st.columns(3)
    with c1:
        card("Authority inference pressure", str(surface["pressure"]), "Ecosystem pressure")
    with c2:
        card("Observed verdict", result["observed_verdict"], result["reason"])
    with c3:
        card("Authority", "NO", "Surface cannot grant authority")

    dark_table([
        {"Check": "Current proof", "Value": current_proof, "Boundary": "Current proof required", "Authority": "NO"},
        {"Check": "Current authority", "Value": current_authority, "Boundary": "Current authority required", "Authority": "NO"},
        {"Check": "Current bind", "Value": current_bind, "Boundary": "Current bind required", "Authority": "NO"},
        {"Check": "Ecosystem surface", "Value": surface["name"], "Boundary": surface["boundary"], "Authority": "NO"},
    ])

    payload = finalize_report_hash({
        "module": "authority_inference_challenge_pack",
        "result": result,
        "boundary": "Public visibility must not become inferred authority.",
    })
    st.download_button(
        ui_text("Download JSON"),
        json.dumps(payload, indent=2, ensure_ascii=False),
        f"CARE_v12_4_authority_inference_{payload.get('runtime_id', rid())}.json",
        "application/json",
        key=f"json_v124_authority_inference_{payload.get('runtime_id', rid())}",
    )

