# ============================================================
# CARE Runtime v19.0 — Runtime Self-Test Center
# Static self-inspection only. It does not create authority,
# bind, execution, permission, or real-world consequence.
# ============================================================

def v125_grouped_unique_pages() -> List[str]:
    pages: List[str] = []
    seen = set()
    for group_pages in GROUPS.values():
        for page in group_pages:
            if page not in seen:
                pages.append(page)
                seen.add(page)
    return pages

def v125_source_for_page(page: str) -> str:
    fn = ROUTES.get(page)
    if not callable(fn):
        return ""
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""

def v125_extract_streamlit_keys(src: str) -> List[str]:
    return re.findall(r"key\s*=\s*[\"']([^\"']+)[\"']", src)

def v125_self_test_rows() -> List[Dict[str, Any]]:
    en_labels = PAGE_LABELS.get("English", {})
    da_labels = PAGE_LABELS.get("Dansk", {})
    rows: List[Dict[str, Any]] = []

    for page in v125_grouped_unique_pages():
        src = v125_source_for_page(page)
        route_ok = page in ROUTES and callable(ROUTES.get(page))
        en_ok = bool(en_labels.get(page))
        da_ok = bool(da_labels.get(page))
        hero_ok = f'render_hero("{page}")' in src or "render_hero(" in src
        content_ok = any(token in src for token in ["st.markdown", "st.info", "st.success", "st.warning", "dark_table(", "card(", "panel(", "st.write"])
        json_ok = "download_button" in src or "st.download_button" in src
        pdf_ok = "pdf_download_button" in src or "external_pdf" in src or "integration_pdf" in src
        runtime_id_ok = "payload.get('runtime_id', rid())" in src or 'payload.get("runtime_id", rid())' in src or "finalize_report_hash(" in src or "runtime_id" not in src
        direct_payload_key_risk = bool(re.search(r"payload\[['\"]runtime_id['\"]\]", src))
        keys = v125_extract_streamlit_keys(src)
        duplicate_key_risk = len(keys) != len(set(keys))
        page_pass = route_ok and en_ok and da_ok and content_ok and runtime_id_ok and not direct_payload_key_risk and not duplicate_key_risk

        rows.append({
            "Page": page,
            "Registered route": "PASS" if route_ok else "HOLD",
            "English label": "PASS" if en_ok else "HOLD",
            "Danish label": "PASS" if da_ok else "HOLD",
            "Hero signal": "PASS" if hero_ok else "HOLD",
            "Content signal": "PASS" if content_ok else "HOLD",
            "JSON signal": "PASS" if json_ok else "HOLD",
            "PDF signal": "PASS" if pdf_ok else "HOLD",
            "Runtime ID safety": "PASS" if runtime_id_ok and not direct_payload_key_risk else "HOLD",
            "Duplicate key risk": "HOLD" if duplicate_key_risk else "PASS",
            "Self-test result": "PASS" if page_pass else "HOLD",
            "Authority": "NO",
        })

    return rows

def v125_self_test_summary() -> Dict[str, Any]:
    rows = v125_self_test_rows()
    total = len(rows)
    pass_count = sum(1 for r in rows if r["Self-test result"] == "PASS")
    hold_count = total - pass_count
    json_count = sum(1 for r in rows if r["JSON signal"] == "PASS")
    pdf_count = sum(1 for r in rows if r["PDF signal"] == "PASS")
    try:
        finalizer_src = inspect.getsource(finalize_report_hash)
    except Exception:
        finalizer_src = ""
    return {
        "total_pages": total,
        "pass_count": pass_count,
        "hold_count": hold_count,
        "json_surface_count": json_count,
        "pdf_surface_count": pdf_count,
        "routes_registered": len(ROUTES),
        "group_count": len(GROUPS),
        "non_authority_guards": len(NON_AUTHORITY_GUARD),
        "runtime_id_normalization": "PASS" if "report.setdefault(\"runtime_id\", rid())" in finalizer_src else "HOLD",
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
    }

def page_runtime_self_test_center() -> None:
    render_hero("runtime_self_test_center")
    st.info(ui_text("CARE can inspect its public runtime surfaces, but inspection does not create authority."))

    summary = v125_self_test_summary()
    c1, c2, c3, c4 = st.columns(4)
    with c1:
        card("Static scan", str(summary["total_pages"]), "Grouped unique pages")
    with c2:
        card("PASS", str(summary["pass_count"]), "Static self-test")
    with c3:
        card("Review needed", str(summary["hold_count"]), "HOLD surfaces")
    with c4:
        card("Authority", "NO", "Self-test is observer-only")

    rows = v125_self_test_rows()
    dark_table(rows)

    if summary["hold_count"] == 0:
        st.success(ui_text("All checked surfaces passed static self-test."))
    else:
        st.warning(ui_text("Some checked surfaces require review."))

    payload = finalize_report_hash({
        "module": "runtime_self_test_center",
        "summary": summary,
        "rows": rows,
        "boundary": "Self-test PASS does not grant permission. Self-test HOLD means review.",
    })

    st.download_button(
        ui_text("Download JSON"),
        json.dumps(payload, indent=2, ensure_ascii=False),
        f"CARE_v12_5_runtime_self_test_{payload.get('runtime_id', rid())}.json",
        "application/json",
        key=f"json_v125_self_test_{payload.get('runtime_id', rid())}",
    )

