def v1251_page_payload(page_key: str, rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    return finalize_report_hash({
        "module": page_key,
        "language": current_lang(),
        "rows": rows,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "human_consequence_allowed": False,
        "boundary": "Content completion is not authority.",
    })

def v1251_completed_page(page_key: str, pdf_title_en: str, pdf_title_da: str, file_prefix: str) -> None:
    render_hero(page_key)
    st.info(ui_text("This page is now completed in both English and Danish."))
    rows = v1251_rows(page_key)

    if page_key == "why_care_exists":
        c1, c2, c3 = st.columns(3)
        with c1:
            card("Why CARE exists" if not v1251_is_danish() else "Hvorfor CARE findes", "Human consequence" if not v1251_is_danish() else "Menneskelig konsekvens", "Purpose ≠ Authority" if not v1251_is_danish() else "Formål ≠ Autoritet")
        with c2:
            card("UNKNOWN -> HOLD" if not v1251_is_danish() else "UKENDT -> HOLD", "No promotion" if not v1251_is_danish() else "Ingen promovering", "Missing grounding stops consequence" if not v1251_is_danish() else "Manglende grundlag stopper konsekvens")
        with c3:
            card("No bind" if not v1251_is_danish() else "Ingen bind", "No human consequence" if not v1251_is_danish() else "Ingen menneskelig konsekvens", "Human surface protected" if not v1251_is_danish() else "Menneskelig flade beskyttet")
    else:
        c1, c2, c3, c4 = st.columns(4)
        with c1:
            card("Rows" if not v1251_is_danish() else "Rækker", str(len(rows)), "Completed content" if not v1251_is_danish() else "Udfyldt indhold")
        with c2:
            card("Language" if not v1251_is_danish() else "Sprog", current_lang(), "Danish/English" if not v1251_is_danish() else "Dansk/engelsk")
        with c3:
            card("Authority", "NO", "Content ≠ Authority" if not v1251_is_danish() else "Indhold ≠ Autoritet")
        with c4:
            card("Boundary" if not v1251_is_danish() else "Grænse", "HOLD", "UNKNOWN -> HOLD" if not v1251_is_danish() else "UKENDT -> HOLD")

    dark_table(rows)

    explanation = (
        "This window is completed. It explains CARE without granting permission, authority, execution, bind, or real-world consequence."
        if not v1251_is_danish()
        else "Dette vindue er udfyldt. Det forklarer CARE uden at give tilladelse, autoritet, eksekvering, bind eller virkelig konsekvens."
    )
    panel("Content completion" if not v1251_is_danish() else "Indholdsudfyldning", explanation)

    payload = v1251_page_payload(page_key, rows)
    json_label = "Download JSON" if not v1251_is_danish() else "Download JSON"
    json_download_button(json_label, payload, file_prefix)
    external_pdf(
        page_key,
        pdf_title_da if v1251_is_danish() else pdf_title_en,
        "Content completion is not authority." if not v1251_is_danish() else "Indholdsudfyldning er ikke autoritet.",
        rows,
        file_prefix,
        payload=payload,
    )

