def page_challenge_care() -> None:
    render_hero("challenge_care")
    st.info(ui_text("Challenge accepted. Authority not granted."))
    rows = v1251_rows("challenge_care")
    dark_table(rows)

    attempts = ["Authority", "Bind", "Permission", "Execution", "Human consequence"] if not v1251_is_danish() else ["Autoritet", "Bind", "Tilladelse", "Eksekvering", "Menneskelig konsekvens"]
    sources = ["Visibility", "QA report", "Citation / DOI", "Demo output", "External feedback", "Public trust"] if not v1251_is_danish() else ["Synlighed", "QA-rapport", "Citation / DOI", "Demo-output", "Ekstern feedback", "Offentlig tillid"]
    attempt = st.selectbox("Attempt" if not v1251_is_danish() else "Forsøg", attempts, key="v1251_challenge_attempt")
    source = st.selectbox("Source" if not v1251_is_danish() else "Kilde", sources, key="v1251_challenge_source")

    if st.button("Challenge CARE" if not v1251_is_danish() else "Udfordr CARE", key="run_v1251_challenge", type="primary"):
        result = {
            "attempt": attempt,
            "source": source,
            "care_result": "NO VALID BIND / NO AUTHORITY" if not v1251_is_danish() else "INTET GYLDIGT BIND / INGEN AUTORITET",
            "decision": "HOLD",
            "reason": (
                f"{source} cannot create {str(attempt).lower()} without valid current proof-bound authority."
                if not v1251_is_danish()
                else f"{source} kan ikke skabe {str(attempt).lower()} uden gyldig aktuel proof-bound autoritet."
            ),
            "authority_granted": False,
            "bind_granted": False,
            "execution_granted": False,
            "human_consequence_allowed": False,
        }
        st.session_state.v1251_challenge_result = result

    if st.session_state.get("v1251_challenge_result"):
        st.warning("Challenge collapsed to HOLD / no authority." if not v1251_is_danish() else "Challenge kollapsede til HOLD / ingen autoritet.")
        st.json(st.session_state.v1251_challenge_result)

    payload = v1251_page_payload("challenge_care", rows)
    external_pdf("challenge_care", "Challenge CARE" if not v1251_is_danish() else "Udfordr CARE", "Challenge accepted. Authority not granted." if not v1251_is_danish() else "Challenge accepteret. Autoritet ikke givet.", rows, "CARE_v12_5_1_challenge_care", payload=payload)
    json_download_button("Download Challenge JSON" if not v1251_is_danish() else "Download challenge JSON", payload, "CARE_v12_5_1_challenge_care")

def v1251_content_completion_rows() -> List[Dict[str, Any]]:
    rows = []
    for page in V1251_COMPLETED_PAGES:
        if page == "missing_route_guard":
            continue
        fn = ROUTES.get(page)
        has_route = callable(fn)
        try:
            src = inspect.getsource(fn) if has_route else ""
        except Exception:
            src = ""
        rows.append({
            "Page": page,
            "Route": "PASS" if has_route else "HOLD",
            "English label": "PASS" if PAGE_LABELS.get("English", {}).get(page) else "HOLD",
            "Danish label": "PASS" if PAGE_LABELS.get("Dansk", {}).get(page) else "HOLD",
            "Hero": "PASS" if page in HERO else "HOLD",
            "Content": "PASS" if "v1251_completed_page" in src or "dark_table" in src else "HOLD",
            "Authority": "NO",
        })
    return rows

def page_content_completion_audit() -> None:
    render_hero("content_completion_audit")
    st.info(ui_text("A missing route must not silently return to the start page."))
    rows = v1251_content_completion_rows()
    dark_table(rows)
    hold = sum(1 for r in rows if "HOLD" in r.values())
    if hold:
        st.warning(ui_text("Some checked surfaces require review."))
    else:
        st.success(ui_text("All checked surfaces passed static self-test."))
    payload = finalize_report_hash({"module": "content_completion_audit", "rows": rows, "hold_count": hold, "boundary": "Content completion is not authority."})
    json_download_button("Download JSON", payload, "CARE_v12_5_1_content_completion_audit")

def page_danish_localization_audit() -> None:
    render_hero("danish_localization_audit")
    st.info(ui_text("Danish localization is access only. It does not create bind."))
    rows = []
    for page in V1251_COMPLETED_PAGES:
        if page == "missing_route_guard":
            continue
        rows.append({
            "Page": page,
            "Danish label": PAGE_LABELS.get("Dansk", {}).get(page, "MISSING"),
            "Danish hero": "PASS" if page in HERO and "Dansk" in HERO[page] else "HOLD",
            "Danish rows": "PASS" if bool(v1251_rows(page)) or page in ["content_completion_audit", "danish_localization_audit"] else "HOLD",
            "Authority": "NO",
        })
    dark_table(rows)
    payload = finalize_report_hash({"module": "danish_localization_audit", "rows": rows, "boundary": "Danish localization is access only."})
    json_download_button("Download JSON", payload, "CARE_v12_5_1_danish_localization_audit")

def page_missing_route_guard(page_key: str = "unknown") -> None:
    render_hero("missing_route_guard")
    st.warning(ui_text("A missing route must not silently return to the start page."))
    rows = [{
        "Requested page": page_key,
        "Route": "HOLD",
        "Result": "Missing route guard shown",
        "Authority": "NO",
    }]
    if v1251_is_danish():
        rows = [{
            "Ønsket side": page_key,
            "Rute": "HOLD",
            "Resultat": "Manglende rute-vagt vist",
            "Autoritet": "NEJ",
        }]
    dark_table(rows)
    panel("Review" if not v1251_is_danish() else "Review", "The page key exists in navigation or state but has no callable route. This is a review issue, not a fallback to Command Center." if not v1251_is_danish() else "Side-nøglen findes i navigation eller state men har ingen kaldbar rute. Det er et review-problem, ikke en fallback til Kommandocenter.")





