def v1252_lang() -> str:
    return current_lang()

def v1252_da() -> bool:
    return v1252_lang() == "Dansk"

def v1252_grouped_unique_pages() -> List[str]:
    pages: List[str] = []
    seen = set()
    for group_pages in GROUPS.values():
        for page in group_pages:
            if page not in seen:
                pages.append(page)
                seen.add(page)
    return pages

def v1252_source_for_page(page: str) -> str:
    fn = ROUTES.get(page)
    if not callable(fn):
        return ""
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""

def v1252_extract_keys(src: str) -> List[str]:
    return re.findall(r"key\s*=\s*[\"']([^\"']+)[\"']", src)

def v1252_deep_rows() -> List[Dict[str, Any]]:
    en_labels = PAGE_LABELS.get("English", {})
    da_labels = PAGE_LABELS.get("Dansk", {})
    rows: List[Dict[str, Any]] = []
    for page in v1252_grouped_unique_pages():
        src = v1252_source_for_page(page)
        route_ok = page in ROUTES and callable(ROUTES.get(page))
        en_ok = bool(en_labels.get(page))
        da_ok = bool(da_labels.get(page))
        hero_ok = page in HERO and "English" in HERO.get(page, {}) and "Dansk" in HERO.get(page, {})
        content_ok = any(token in src for token in ["st.markdown", "st.info", "st.success", "st.warning", "dark_table(", "card(", "panel(", "st.write"])
        json_ok = "download_button" in src or "json_download_button" in src or "st.download_button" in src
        pdf_ok = "pdf_download_button" in src or "external_pdf" in src or "integration_pdf" in src
        direct_payload_risk = bool(re.search(r"payload\[['\"]runtime_id['\"]\]", src))
        keys = v1252_extract_keys(src)
        duplicate_key_risk = len(keys) != len(set(keys))
        runtime_id_safe = "payload.get('runtime_id', rid())" in src or 'payload.get("runtime_id", rid())' in src or "finalize_report_hash(" in src or "runtime_id" not in src
        result = "PASS" if route_ok and en_ok and da_ok and content_ok and not direct_payload_risk and not duplicate_key_risk and runtime_id_safe else "HOLD"
        if v1252_da():
            rows.append({
                "Side": page,
                "Rute": "PASS" if route_ok else "HOLD",
                "Engelsk label": "PASS" if en_ok else "HOLD",
                "Dansk label": "PASS" if da_ok else "HOLD",
                "Hero": "PASS" if hero_ok else "HOLD",
                "Indhold": "PASS" if content_ok else "HOLD",
                "JSON": "PASS" if json_ok else "HOLD",
                "PDF": "PASS" if pdf_ok else "HOLD",
                "Runtime ID": "PASS" if runtime_id_safe and not direct_payload_risk else "HOLD",
                "Duplicate key": "HOLD" if duplicate_key_risk else "PASS",
                "Review-resultat": result,
                "Autoritet": "NEJ",
            })
        else:
            rows.append({
                "Page": page,
                "Route": "PASS" if route_ok else "HOLD",
                "English label": "PASS" if en_ok else "HOLD",
                "Danish label": "PASS" if da_ok else "HOLD",
                "Hero": "PASS" if hero_ok else "HOLD",
                "Content": "PASS" if content_ok else "HOLD",
                "JSON": "PASS" if json_ok else "HOLD",
                "PDF": "PASS" if pdf_ok else "HOLD",
                "Runtime ID": "PASS" if runtime_id_safe and not direct_payload_risk else "HOLD",
                "Duplicate key": "HOLD" if duplicate_key_risk else "PASS",
                "Review result": result,
                "Authority": "NO",
            })
    return rows

def v1252_summary() -> Dict[str, Any]:
    rows = v1252_deep_rows()
    result_key = "Review-resultat" if v1252_da() else "Review result"
    total = len(rows)
    pass_count = sum(1 for r in rows if r.get(result_key) == "PASS")
    hold_count = total - pass_count
    return {
        "total_pages": total,
        "pass_count": pass_count,
        "hold_count": hold_count,
        "routes_registered": len(ROUTES),
        "groups": len(GROUPS),
        "non_authority_guards": len(NON_AUTHORITY_GUARD),
        "language": current_lang(),
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "human_consequence_allowed": False,
    }

def v1252_boundary_rows() -> List[Dict[str, Any]]:
    if v1252_da():
        return [
            {"Grænse": "Self-test PASS giver ikke tilladelse", "Status": "PASS", "Autoritet": "NEJ"},
            {"Grænse": "Self-test HOLD betyder review", "Status": "PASS", "Autoritet": "NEJ"},
            {"Grænse": "Test-komplethed er ikke governance", "Status": "PASS", "Autoritet": "NEJ"},
            {"Grænse": "Inspektionsresultat er ikke bind", "Status": "PASS", "Autoritet": "NEJ"},
        ]
    return [
        {"Boundary": "Self-test PASS does not grant permission", "Status": "PASS", "Authority": "NO"},
        {"Boundary": "Self-test HOLD means review", "Status": "PASS", "Authority": "NO"},
        {"Boundary": "Test completeness is not governance", "Status": "PASS", "Authority": "NO"},
        {"Boundary": "Inspection result is not bind", "Status": "PASS", "Authority": "NO"},
    ]

