    readiness_label = "Ready for review" if readiness == "PASS" else "Needs review"
    if v126_da():
        readiness_label = "Klar til review" if readiness == "PASS" else "Kræver review"

    c1, c2, c3, c4 = st.columns(4)
    with c1:
        card("Release gate", readiness, readiness_label)
    with c2:
        card("Pages" if not v126_da() else "Sider", str(summary["total_pages"]), "Checked" if not v126_da() else "Tjekket")
    with c3:
        card("HOLD", str(summary["hold_count"]), "Review rows" if not v126_da() else "Review-rækker")
