def v127_da() -> bool:
    return current_lang() == "Dansk"

def v127_pages() -> List[str]:
    pages: List[str] = []
    seen = set()
    for group_pages in GROUPS.values():
        for page in group_pages:
            if page not in seen:
                pages.append(page)
                seen.add(page)
    return pages

def v127_source(page: str) -> str:
    fn = ROUTES.get(page) if "ROUTES" in globals() else None
    if not callable(fn):
        return ""
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""

def v127_route_counts() -> Dict[str, int]:
    try:
        app_src = Path(__file__).read_text(encoding="utf-8")
    except Exception:
        return {}
    matches = list(re.finditer(r"^ROUTES\s*=\s*\{", app_src, flags=re.M))
    if not matches:
        return {}
    block = app_src[matches[-1].start():]
    routes = re.findall(r'"([a-zA-Z0-9_]+)"\s*:\s*page_[a-zA-Z0-9_]+', block)
    counts: Dict[str, int] = {}
    for route in routes:
        counts[route] = counts.get(route, 0) + 1
    return counts

def v127_page_rows() -> List[Dict[str, Any]]:
    en_labels = PAGE_LABELS.get("English", {})
    da_labels = PAGE_LABELS.get("Dansk", {})
    route_counts = v127_route_counts()
    rows: List[Dict[str, Any]] = []
    for page in v127_pages():
        src = v127_source(page)
        route_ok = page in ROUTES and callable(ROUTES.get(page))
        en_label = en_labels.get(page, "")
        da_label = da_labels.get(page, "")
        hero_en = page in HERO and "English" in HERO.get(page, {})
        hero_da = page in HERO and "Dansk" in HERO.get(page, {})
        content_ok = any(tok in src for tok in ["st.markdown", "st.info", "st.success", "st.warning", "dark_table(", "card(", "panel(", "st.write"])
        json_ok = "json_download_button" in src or "st.download_button" in src or "download_button" in src
        pdf_ok = "pdf_download_button" in src or "external_pdf" in src or "integration_pdf" in src
        runtime_id_safe = "payload.get('runtime_id', rid())" in src or 'payload.get("runtime_id", rid())' in src or "finalize_report_hash(" in src or "runtime_id" not in src
        direct_payload_risk = bool(re.search(r"payload\[['\"]runtime_id['\"]\]", src))
        legacy_label = any(p.lower() in (en_label + " " + da_label).lower() for p in V127_LEGACY_PATTERNS)
        route_duplicate = route_counts.get(page, 0) > 1

        completion_bits = [
            route_ok, bool(en_label), bool(da_label), hero_en, hero_da, content_ok,
            runtime_id_safe and not direct_payload_risk, not route_duplicate
        ]
        completion_score = round(100 * sum(1 for bit in completion_bits if bit) / len(completion_bits), 1)

        if v127_da():
            rows.append({
                "Side": page,
                "Rute": "PASS" if route_ok else "HOLD",
                "Engelsk": "PASS" if en_label else "HOLD",
                "Dansk": "PASS" if da_label else "HOLD",
                "Hero EN": "PASS" if hero_en else "HOLD",
                "Hero DK": "PASS" if hero_da else "HOLD",
                "Indhold": "PASS" if content_ok else "HOLD",
                "JSON": "PASS" if json_ok else "HOLD",
                "PDF": "PASS" if pdf_ok else "HOLD",
                "Runtime ID": "PASS" if runtime_id_safe and not direct_payload_risk else "HOLD",
                "Legacy label": "HOLD" if legacy_label else "PASS",
                "Duplicate route": "HOLD" if route_duplicate else "PASS",
                "Completion score": completion_score,
                "Autoritet": "NEJ",
            })
        else:
            rows.append({
                "Page": page,
                "Route": "PASS" if route_ok else "HOLD",
                "English": "PASS" if en_label else "HOLD",
                "Danish": "PASS" if da_label else "HOLD",
                "Hero EN": "PASS" if hero_en else "HOLD",
                "Hero DK": "PASS" if hero_da else "HOLD",
                "Content": "PASS" if content_ok else "HOLD",
                "JSON": "PASS" if json_ok else "HOLD",
                "PDF": "PASS" if pdf_ok else "HOLD",
                "Runtime ID": "PASS" if runtime_id_safe and not direct_payload_risk else "HOLD",
                "Legacy label": "HOLD" if legacy_label else "PASS",
                "Duplicate route": "HOLD" if route_duplicate else "PASS",
                "Completion score": completion_score,
                "Authority": "NO",
            })
    return rows

def v127_summary() -> Dict[str, Any]:
    rows = v127_page_rows()
    score_key = "Completion score"
    total = len(rows)
    avg_score = round(sum(float(r.get(score_key, 0)) for r in rows) / total, 1) if total else 0
    hold_count = sum(1 for r in rows if any(v == "HOLD" for v in r.values()))
    pass_like = total - hold_count
    return {
        "total_pages": total,
        "pass_like_pages": pass_like,
        "hold_pages": hold_count,
        "average_completion_score": avg_score,
        "routes_registered": len(ROUTES),
        "groups": len(GROUPS),
        "legacy_label_candidates": sum(1 for r in rows if r.get("Legacy label") == "HOLD"),
        "download_surfaces_json": sum(1 for r in rows if r.get("JSON") == "PASS"),
        "download_surfaces_pdf": sum(1 for r in rows if r.get("PDF") == "PASS"),
        "language": current_lang(),
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
    }

def v127_boundary_rows() -> List[Dict[str, Any]]:
    if v127_da():
        return [
            {"Grænse": "Completion score er ikke autoritet", "Status": "PASS", "Autoritet": "NEJ"},
            {"Grænse": "Search result er ikke bind", "Status": "PASS", "Autoritet": "NEJ"},
            {"Grænse": "Sidebar cleanup er ikke tilladelse", "Status": "PASS", "Autoritet": "NEJ"},
            {"Grænse": "Downloadflade er ikke deployment-autoritet", "Status": "PASS", "Autoritet": "NEJ"},
        ]
    return [
        {"Boundary": "Completion score is not authority", "Status": "PASS", "Authority": "NO"},
        {"Boundary": "Search result is not bind", "Status": "PASS", "Authority": "NO"},
        {"Boundary": "Sidebar cleanup is not permission", "Status": "PASS", "Authority": "NO"},
        {"Boundary": "Download surface is not deployment authority", "Status": "PASS", "Authority": "NO"},
    ]

