def v128_da() -> bool:
    return current_lang() == "Dansk"

def v128_pages() -> List[str]:
    pages: List[str] = []
    seen = set()
    for group_pages in GROUPS.values():
        for page in group_pages:
            if page not in seen:
                pages.append(page)
                seen.add(page)
    return pages

def v128_page_label(page_key: str) -> str:
    lang = current_lang()
    return PAGE_LABELS.get(lang, {}).get(page_key) or PAGE_LABELS.get("English", {}).get(page_key) or page_key.replace("_", " ").title()

def v128_category(page_key: str) -> str:
    p = page_key.lower()
    if any(x in p for x in ["why", "journey", "story", "founder", "nick", "mission", "milestone"]):
        return "story"
    if any(x in p for x in ["audit", "qa", "test", "scoreboard", "health", "completion"]):
        return "audit"
    if any(x in p for x in ["authority", "bind", "admissibility", "governance", "inference"]):
        return "authority"
    if any(x in p for x in ["challenge", "red_team", "pressure", "attack"]):
        return "challenge"
    if any(x in p for x in ["download", "pdf", "export", "json"]):
        return "export"
    if any(x in p for x in ["language", "translation", "danish", "bilingual"]):
        return "language"
    if any(x in p for x in ["academy", "dictionary", "learning", "guide"]):
        return "learning"
    if any(x in p for x in ["human", "patient", "hospital", "citizen", "consequence"]):
        return "human"
    return "runtime"

