def sidebar() -> str:
    lang = language_selector()
    labels = PAGE_LABELS.get(lang, PAGE_LABELS.get("English", {}))

    st.sidebar.markdown("## CARE Runtime v19.0")
    st.sidebar.caption("Global Search + Timeline + Founder Center · vNEXT858 · vNEXT859 HOLD")

    founder_label = "Founder of CARE" if lang == "English" else "Founder af CARE"
    st.sidebar.markdown(
        f"""
        <div style="padding:12px;border:1px solid rgba(250,204,21,.45);border-radius:14px;background:rgba(250,204,21,.08);margin:10px 0;">
          <div style="font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:#facc15;font-weight:900;">{founder_label}</div>
          <div style="font-size:1rem;font-weight:900;color:#fff;">Nick Vejle</div>
          <div style="font-size:.78rem;color:#fde68a;">Observer-only public demo</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    current = st.session_state.get("page_key", "command_center")
    if current not in ROUTES:
        current = "command_center"

    st.sidebar.markdown("### " + ("Navigation" if lang == "English" else "Navigation"))

    # Flatten grouped pages with section markers.
    option_keys: List[str] = []
    option_labels: List[str] = []
    option_to_key: Dict[str, str] = {}

    for group_name, pages in GROUPS.items():
        group_label = GROUP_LABELS.get(lang, GROUP_LABELS.get("English", {})).get(group_name, group_name)
        for page in pages:
            if page not in ROUTES:
                continue
            page_label = labels.get(page, page.replace("_", " ").title())
            display = f"{group_label} · {page_label}"
            # Make labels unique if repeated
            if display in option_to_key:
                display = f"{display} [{page}]"
            option_keys.append(page)
            option_labels.append(display)
            option_to_key[display] = page

    if "command_center" in ROUTES and "command_center" not in option_keys:
        display = labels.get("command_center", "Command Center")
        option_keys.insert(0, "command_center")
        option_labels.insert(0, display)
        option_to_key[display] = "command_center"

    try:
        current_index = option_keys.index(current)
    except ValueError:
        current_index = 0

    selected_label = st.sidebar.selectbox(
        "Section" if lang == "English" else "Sektion",
        option_labels,
        index=current_index,
        key="v1281_sidebar_route_selector",
    )
    selected_page = option_to_key.get(selected_label, "command_center")
    st.session_state["page_key"] = selected_page

    st.sidebar.markdown("---")
    st.sidebar.caption(
        ("Selected page: " if lang == "English" else "Valgt side: ")
        + labels.get(selected_page, selected_page)
    )

    st.sidebar.markdown(
        """
        <div style="font-size:.75rem;color:#9ca3af;line-height:1.35;margin-top:12px;">
        Navigation is access only. It does not create authority, bind, execution, permission, or consequence.
        </div>
        """,
        unsafe_allow_html=True,
    )
    return selected_page

