# ============================================================
# CARE Runtime v19.0 — Runtime Recovery Diagnostic
# Verifies language selector, sidebar route state and route references.
# ============================================================

def page_runtime_recovery_diagnostic() -> None:
    render_hero("runtime_recovery_diagnostic")
    lang = current_lang()
    st.info(
        "Runtime recovery check: language selector, sidebar state and route references."
        if lang == "English"
        else "Runtime recovery-tjek: language selector, sidebar state og route-referencer."
    )

    route_pairs = []
    try:
        app_src = Path(__file__).read_text(encoding="utf-8")
        matches = list(re.finditer(r"^ROUTES\s*=\s*\{", app_src, flags=re.M))
        if matches:
            block = app_src[matches[-1].start():]
            route_pairs = re.findall(r'"([a-zA-Z0-9_]+)"\s*:\s*(page_[A-Za-z0-9_]+)', block)
    except Exception:
        route_pairs = []

    missing = []
    for route, fn in route_pairs:
        if fn not in globals() or not callable(globals().get(fn)):
            missing.append({"route": route, "function": fn, "status": "MISSING"})

    rows = [
        {
            "Check" if lang == "English" else "Tjek": "language_selector",
            "Result" if lang == "English" else "Resultat": "PASS" if callable(globals().get("language_selector")) else "HOLD",
            "Authority" if lang == "English" else "Autoritet": "NO" if lang == "English" else "NEJ",
        },
        {
            "Check" if lang == "English" else "Tjek": "selected page",
            "Result" if lang == "English" else "Resultat": st.session_state.get("page_key", "not selected"),
            "Authority" if lang == "English" else "Autoritet": "NO" if lang == "English" else "NEJ",
        },
        {
            "Check" if lang == "English" else "Tjek": "route functions",
            "Result" if lang == "English" else "Resultat": "PASS" if not missing else f"HOLD: {len(missing)} missing",
            "Authority" if lang == "English" else "Autoritet": "NO" if lang == "English" else "NEJ",
        },
        {
            "Check" if lang == "English" else "Tjek": "route count",
            "Result" if lang == "English" else "Resultat": len(ROUTES),
            "Authority" if lang == "English" else "Autoritet": "NO" if lang == "English" else "NEJ",
        },
    ]
    dark_table(rows)

    if missing:
        st.warning("Missing route functions found." if lang == "English" else "Manglende route functions fundet.")
        dark_table(missing)
    else:
        st.success("Runtime recovery checks passed." if lang == "English" else "Runtime recovery-tjek bestået.")

    payload = finalize_report_hash({
        "module": "runtime_recovery_diagnostic",
        "language_selector_present": callable(globals().get("language_selector")),
        "selected_page": st.session_state.get("page_key"),
        "route_count": len(ROUTES),
        "missing_route_functions": missing,
        "boundary": "Recovery diagnostics are review-only.",
    })
    json_download_button("Download JSON", payload, "CARE_v12_8_2_runtime_recovery_diagnostic")





