def v129_summary_numbers() -> Dict[str, Any]:
    try:
        total_routes = len(ROUTES)
    except Exception:
        total_routes = 0
    try:
        total_groups = len(GROUPS)
    except Exception:
        total_groups = 0
    try:
        guards = len(NON_AUTHORITY_GUARD)
    except Exception:
        guards = 0
    try:
        dk_labels = len(PAGE_LABELS.get("Dansk", {}))
        en_labels = len(PAGE_LABELS.get("English", {}))
    except Exception:
        dk_labels = 0
        en_labels = 0
    return {
        "routes": total_routes,
        "groups": total_groups,
        "guards": guards,
        "dk_labels": dk_labels,
        "en_labels": en_labels,
        "version": PLATFORM_NAME,
    }

