# Professional sidebar override, replacing the long prototype-style list with a two-level selector.
def sidebar() -> str:
    lang = language_selector()
    labels = PAGE_LABELS.get(lang, PAGE_LABELS.get("English", {}))

    st.sidebar.markdown(
        """
        <div style="padding:16px 14px;border:1px solid rgba(250,204,21,.35);border-radius:20px;
                    background:linear-gradient(135deg,rgba(250,204,21,.10),rgba(96,165,250,.06));margin:8px 0 14px 0;">
          <div style="font-size:.68rem;letter-spacing:.16em;text-transform:uppercase;color:#facc15;font-weight:950;">CARE Runtime v19.0</div>
          <div style="font-size:1.25rem;font-weight:950;color:#fff;letter-spacing:-.04em;">Mission Control</div>
          <div style="font-size:.78rem;color:#cbd5e1;margin-top:4px;">Professional Platform UI · vNEXT858 · vNEXT859 HOLD</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    st.sidebar.markdown(
        """
        <div style="padding:12px;border:1px solid rgba(148,163,184,.20);border-radius:16px;background:rgba(15,23,42,.68);margin-bottom:14px;">
          <div style="font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:#94a3b8;font-weight:900;">Founder of CARE</div>
          <div style="font-size:1.05rem;font-weight:950;color:#fff;">Nick Vejle</div>
          <div style="font-size:.78rem;color:#fde68a;">Observer-only public demo</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    group_keys = list(GROUPS.keys())
    current_page = st.session_state.get("page_key", "command_center")
    current_group = "command"
    for g, pages in GROUPS.items():
        if current_page in pages:
            current_group = g
            break

    group_labels = GROUP_LABELS.get(lang, GROUP_LABELS.get("English", {}))
    selected_group = st.sidebar.selectbox(
        "Workspace" if lang == "English" else "Workspace",
        group_keys,
        index=group_keys.index(current_group) if current_group in group_keys else 0,
        format_func=lambda g: group_labels.get(g, g.replace("_", " ").title()),
        key="v129_sidebar_workspace",
    )

    pages = [p for p in GROUPS.get(selected_group, []) if p in ROUTES]
    if not pages:
        pages = ["command_center"]

    if current_page not in pages:
        current_page = pages[0]

    selected_page = st.sidebar.selectbox(
        "Page" if lang == "English" else "Side",
        pages,
        index=pages.index(current_page) if current_page in pages else 0,
        format_func=lambda p: labels.get(p, p.replace("_", " ").title()),
        key="v129_sidebar_page",
    )

    st.session_state["page_key"] = selected_page

    st.sidebar.markdown("---")
    st.sidebar.caption(("Selected: " if lang == "English" else "Valgt: ") + labels.get(selected_page, selected_page))
    st.sidebar.caption("Navigation is access only · no authority · no bind")

    return selected_page




