def v130_compact_public_stats() -> None:
    nums = v129_summary_numbers() if callable(globals().get("v129_summary_numbers")) else {"routes": len(ROUTES), "groups": len(GROUPS), "guards": len(NON_AUTHORITY_GUARD)}
    stats = [
        ("Routes" if not v130_da() else "Ruter", str(nums.get("routes", len(ROUTES))), "public demo pages" if not v130_da() else "public demo-sider"),
        ("Mode", "Observer-only", "no real-world action" if not v130_da() else "ingen virkelig handling"),
        ("Boundary" if not v130_da() else "Grænse", "UNKNOWN -> HOLD", "safe default" if not v130_da() else "sikkert default"),
        ("Authority" if not v130_da() else "Autoritet", "NO", "demo never authorizes" if not v130_da() else "demo autoriserer aldrig"),
    ]
    if callable(globals().get("v129_stats")):
        v129_stats(stats)
