# v13.0: shorter public sidebar for first impression.
def sidebar() -> str:
    lang = language_selector()
    labels = PAGE_LABELS.get(lang, PAGE_LABELS.get("English", {}))

    st.sidebar.markdown(
        """
        <div style="padding:16px 14px;border:1px solid rgba(250,204,21,.35);border-radius:20px;
                    background:linear-gradient(135deg,rgba(250,204,21,.10),rgba(96,165,250,.06));margin:8px 0 14px 0;">
          <div style="font-size:.68rem;letter-spacing:.16em;text-transform:uppercase;color:#facc15;font-weight:950;">CARE Runtime v19.0</div>
          <div style="font-size:1.25rem;font-weight:950;color:#fff;letter-spacing:-.04em;">Global Search + Timeline + Founder Center</div>
          <div style="font-size:.78rem;color:#cbd5e1;margin-top:4px;">Observer-only · vNEXT858 · vNEXT859 HOLD</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    public_map = {
        "Start": ["command_center", "start_here_public_demo", "professional_mission_control", "executive_overview_center"],
        "Story": ["why_care_exists", "founder_timeline_center", "public_nick_vejle_context", "journey_to_care"],
        "Audit": ["care_runtime_completion_center", "full_runtime_completion_audit", "runtime_recovery_diagnostic", "sidebar_navigation_diagnostic"],
        "Testing": ["reviewer_mode", "public_demo_flow", "care_challenge_arena", "authority_inference_challenge_pack"],
        "Downloads": ["clean_download_center", "download_surface_center", "download_surface_audit"],
        "All pages": [p for group_pages in GROUPS.values() for p in group_pages],
    }

    if lang == "Dansk":
        workspace_labels = {
            "Start": "Start",
            "Story": "Historie",
            "Audit": "Audit",
            "Testing": "Testing",
            "Downloads": "Downloads",
            "All pages": "Alle sider",
        }
    else:
        workspace_labels = {k: k for k in public_map}

    current_page = st.session_state.get("page_key", "command_center")
    current_workspace = "Start"
    for w, pages in public_map.items():
        if current_page in pages:
            current_workspace = w
            break

    workspaces = list(public_map.keys())
    selected_workspace = st.sidebar.selectbox(
        "Workspace",
        workspaces,
        index=workspaces.index(current_workspace),
        format_func=lambda w: workspace_labels.get(w, w),
        key="v130_sidebar_workspace",
    )

    pages = []
    seen = set()
    for p in public_map.get(selected_workspace, []):
        if p in ROUTES and p not in seen:
            pages.append(p)
            seen.add(p)
    if not pages:
        pages = ["command_center"]

    if current_page not in pages:
        current_page = pages[0]

    selected_page = st.sidebar.selectbox(
        "Page" if lang == "English" else "Side",
        pages,
        index=pages.index(current_page) if current_page in pages else 0,
        format_func=lambda p: labels.get(p, p.replace("_", " ").title()),
        key="v130_sidebar_page",
    )

    st.session_state["page_key"] = selected_page

    st.sidebar.markdown("---")
    st.sidebar.caption(("Selected: " if lang == "English" else "Valgt: ") + labels.get(selected_page, selected_page))
    st.sidebar.caption("Public demo · no authority · no bind · no execution")
    return selected_page





