def v140_da() -> bool:
    return current_lang() == "Dansk"

def v140_eval(proof: bool, authority: bool, current_state: bool, bind: bool) -> Dict[str, Any]:
    if not proof:
        decision = "HOLD"
        reason_en = "Current proof is missing."
        reason_da = "Aktuelt bevis mangler."
    elif not authority:
        decision = "HOLD"
        reason_en = "Current authority is missing."
        reason_da = "Aktuel autoritet mangler."
    elif not current_state:
        decision = "HOLD"
        reason_en = "Current state is not verified."
        reason_da = "Aktuel tilstand er ikke verificeret."
    elif not bind:
        decision = "HOLD"
        reason_en = "Valid bind is missing."
        reason_da = "Gyldigt bind mangler."
    else:
        decision = "PASS"
        reason_en = "All review-only demo conditions are present. This still grants no real-world authority."
        reason_da = "Alle review-only demo-betingelser er til stede. Det giver stadig ingen virkelig autoritet."
    return {
        "decision": decision,
        "reason": reason_da if v140_da() else reason_en,
        "authority_granted": False,
        "bind_granted": False,
        "execution_granted": False,
        "permission_granted": False,
        "human_consequence_allowed": False if decision != "PASS" else "DEMO_ONLY_NO_REAL_WORLD_EFFECT",
    }

def v140_status_rows() -> List[Dict[str, Any]]:
    if v140_da():
        return [
            {"CARE-regel": "No proof -> no bind -> no effect-capable path -> no effect", "Menneskelig betydning": "Hvis grundlaget mangler, må konsekvens ikke nå mennesket.", "Autoritet": "NEJ"},
            {"CARE-regel": "UNKNOWN -> HOLD", "Menneskelig betydning": "Usikkerhed må ikke blive skade.", "Autoritet": "NEJ"},
            {"CARE-regel": "No bind -> no human consequence", "Menneskelig betydning": "Ingen gyldig bind, ingen virkelig menneskelig konsekvens.", "Autoritet": "NEJ"},
        ]
    return [
        {"CARE rule": "No proof -> no bind -> no effect-capable path -> no effect", "Human meaning": "If grounding is missing, consequence must not reach the human.", "Authority": "NO"},
        {"CARE rule": "UNKNOWN -> HOLD", "Human meaning": "Uncertainty must not become harm.", "Authority": "NO"},
        {"CARE rule": "No bind -> no human consequence", "Human meaning": "No valid bind, no real human consequence.", "Authority": "NO"},
    ]

