def page_interactive_scenario_builder() -> None:
    render_hero("interactive_scenario_builder")
    st.info("Build a scenario. CARE will not grant real-world authority." if not v140_da() else "Byg et scenario. CARE giver ikke virkelig autoritet.")

    if v140_da():
        scenario = st.selectbox("Scenariotype", ["Kommune / ydelse", "Hospital / patient", "Arbejde / sikkerhed", "Familie / støtte"], key="v140_scenario_type")
        human = st.selectbox("Berørt menneske", ["Borger", "Patient", "Medarbejder", "Familie"], key="v140_human")
        consequence = st.selectbox("Konsekvens", ["Ydelse stoppes", "Behandling ændres", "Adgang nægtes", "Støtte forsinkes"], key="v140_consequence")
    else:
        scenario = st.selectbox("Scenario type", ["Municipality / benefit", "Hospital / patient", "Work / safety", "Family / support"], key="v140_scenario_type")
        human = st.selectbox("Affected human", ["Citizen", "Patient", "Worker", "Family"], key="v140_human")
        consequence = st.selectbox("Consequence", ["Benefit stopped", "Treatment changed", "Access denied", "Support delayed"], key="v140_consequence")

    c1, c2, c3, c4 = st.columns(4)
    with c1:
        proof = st.checkbox("Current proof" if not v140_da() else "Aktuelt bevis", value=False, key="v140_proof")
    with c2:
        authority = st.checkbox("Current authority" if not v140_da() else "Aktuel autoritet", value=False, key="v140_authority")
    with c3:
        current_state = st.checkbox("Current state" if not v140_da() else "Aktuel tilstand", value=False, key="v140_state")
    with c4:
        bind = st.checkbox("Valid bind" if not v140_da() else "Gyldigt bind", value=False, key="v140_bind")

    result = v140_eval(proof, authority, current_state, bind)

    if result["decision"] == "PASS":
        st.success(f"CARE result: {result['decision']} — {result['reason']}")
    else:
        st.warning(f"CARE result: {result['decision']} — {result['reason']}")

    rows = [{
        "Scenario type" if not v140_da() else "Scenariotype": scenario,
        "Affected human" if not v140_da() else "Berørt menneske": human,
        "Consequence" if not v140_da() else "Konsekvens": consequence,
        "Current proof" if not v140_da() else "Aktuelt bevis": proof,
        "Current authority" if not v140_da() else "Aktuel autoritet": authority,
        "Current state" if not v140_da() else "Aktuel tilstand": current_state,
        "Valid bind" if not v140_da() else "Gyldigt bind": bind,
        "CARE result" if not v140_da() else "CARE-resultat": result["decision"],
        "Reason" if not v140_da() else "Årsag": result["reason"],
        "Authority" if not v140_da() else "Autoritet": "NO" if not v140_da() else "NEJ",
    }]
    dark_table(rows)

    payload = finalize_report_hash({"module": "interactive_scenario_builder", "scenario": rows[0], "result": result, "boundary": "Scenario result is not real-world authority."})
    json_download_button("Download Scenario JSON", payload, "CARE_v14_0_interactive_scenario_builder")

