def v150_da() -> bool:
    return current_lang() == "Dansk"

def v150_routes_health() -> Dict[str, Any]:
    route_pairs = []
    try:
        app_src = Path(__file__).read_text(encoding="utf-8")
        matches = list(re.finditer(r"^ROUTES\s*=\s*\{", app_src, flags=re.M))
        if matches:
            block = app_src[matches[-1].start():]
            route_pairs = re.findall(r'"([a-zA-Z0-9_]+)"\s*:\s*(page_[A-Za-z0-9_]+)', block)
    except Exception:
        route_pairs = list(ROUTES.items())

    missing = []
    for route, fn in route_pairs:
        fn_name = fn if isinstance(fn, str) else getattr(fn, "__name__", str(fn))
        if isinstance(fn, str):
            ok = callable(globals().get(fn))
        else:
            ok = callable(fn)
        if not ok:
            missing.append({"route": route, "function": fn_name, "status": "MISSING"})
    return {
        "route_count": len(ROUTES),
        "group_count": len(GROUPS),
        "guard_count": len(NON_AUTHORITY_GUARD),
        "english_labels": len(PAGE_LABELS.get("English", {})),
        "danish_labels": len(PAGE_LABELS.get("Dansk", {})),
        "missing_route_functions": missing,
        "st_navigation_available": hasattr(st, "navigation") and hasattr(st, "Page"),
    }

def page_v15_runtime_health_center() -> None:
    render_hero("v15_runtime_health_center")
    h = v150_routes_health()

    if callable(globals().get("v129_stats")):
        v129_stats([
            ("Routes" if not v150_da() else "Ruter", str(h["route_count"]), "all available" if not v150_da() else "alle tilgængelige"),
            ("Groups" if not v150_da() else "Grupper", str(h["group_count"]), "organized" if not v150_da() else "organiseret"),
            ("Native nav" if not v150_da() else "Native nav", "YES" if h["st_navigation_available"] else "NO", "st.Page / st.navigation"),
            ("Missing" if not v150_da() else "Mangler", str(len(h["missing_route_functions"])), "route functions" if not v150_da() else "route functions"),
        ])

    rows = [
        {"Health check": "Streamlit native navigation", "Result": "Available" if h["st_navigation_available"] else "Fallback router active", "Boundary": "Navigation ≠ Authority"},
        {"Health check": "Public sidebar simplified", "Result": "PASS", "Boundary": "Simplicity ≠ Permission"},
        {"Health check": "Advanced archive available", "Result": "PASS", "Boundary": "Archive ≠ Execution"},
        {"Health check": "Route function integrity", "Result": "PASS" if not h["missing_route_functions"] else f"HOLD: {len(h['missing_route_functions'])} missing", "Boundary": "Integrity ≠ Bind"},
        {"Health check": "Danish/English labels", "Result": f"EN {h['english_labels']} / DK {h['danish_labels']}", "Boundary": "Language ≠ Authority"},
    ]
    if v150_da():
        rows = [
            {"Health-tjek": "Streamlit native navigation", "Resultat": "Tilgængelig" if h["st_navigation_available"] else "Fallback-router aktiv", "Grænse": "Navigation ≠ Autoritet"},
            {"Health-tjek": "Offentlig sidebar forenklet", "Resultat": "PASS", "Grænse": "Enkelhed ≠ Tilladelse"},
            {"Health-tjek": "Advanced archive tilgængelig", "Resultat": "PASS", "Grænse": "Archive ≠ Eksekvering"},
            {"Health-tjek": "Route function integrity", "Resultat": "PASS" if not h["missing_route_functions"] else f"HOLD: {len(h['missing_route_functions'])} missing", "Grænse": "Integritet ≠ Bind"},
            {"Health-tjek": "Dansk/engelsk labels", "Resultat": f"EN {h['english_labels']} / DK {h['danish_labels']}", "Grænse": "Sprog ≠ Autoritet"},
        ]
    dark_table(rows)

    if h["missing_route_functions"]:
        st.warning("Missing route functions found." if not v150_da() else "Manglende route functions fundet.")
        dark_table(h["missing_route_functions"])

    payload = finalize_report_hash({"module": "v15_runtime_health_center", "health": h, "boundary": "Runtime health is review-only."})
    json_download_button("Download Runtime Health JSON", payload, "CARE_v15_0_runtime_health")

