def v151_route_keys() -> List[str]:
    return list(dict.fromkeys(ROUTES.keys()))

def v151_language_audit_payload() -> Dict[str, Any]:
    routes = v151_route_keys()
    en_labels = PAGE_LABELS.get("English", {})
    dk_labels = PAGE_LABELS.get("Dansk", {})

    missing_en_labels = [r for r in routes if not en_labels.get(r)]
    missing_dk_labels = [r for r in routes if not dk_labels.get(r)]

    hero_keys = sorted(set(HERO.keys()))
    missing_en_hero = [k for k in hero_keys if "English" not in HERO.get(k, {})]
    missing_dk_hero = [k for k in hero_keys if "Dansk" not in HERO.get(k, {})]

    # Heuristic: Danish labels that are identical to English labels may be okay for product names,
    # but they are flagged for review because public Danish demo should be intentional.
    identical_labels = []
    for r in routes:
        if en_labels.get(r) and dk_labels.get(r) and en_labels.get(r) == dk_labels.get(r):
            if r not in {"command_center"} and "CARE" not in en_labels.get(r, "") and "Runtime" not in en_labels.get(r, ""):
                identical_labels.append(r)

    core_copy_missing = []
    for key, entry in V151_CORE_COPY.items():
        if not entry.get("English") or not entry.get("Dansk"):
            core_copy_missing.append(key)

    coverage_total = max(1, len(routes) * 2 + len(hero_keys) * 2 + len(V151_CORE_COPY) * 2)
    missing_total = len(missing_en_labels) + len(missing_dk_labels) + len(missing_en_hero) + len(missing_dk_hero) + len(core_copy_missing)
    completion = round(100 * (coverage_total - missing_total) / coverage_total, 1)

    return {
        "route_count": len(routes),
        "hero_count": len(hero_keys),
        "core_copy_count": len(V151_CORE_COPY),
        "missing_english_labels": missing_en_labels,
        "missing_danish_labels": missing_dk_labels,
        "missing_english_hero": missing_en_hero,
        "missing_danish_hero": missing_dk_hero,
        "identical_labels_review": identical_labels,
        "core_copy_missing": core_copy_missing,
        "coverage_total": coverage_total,
        "missing_total": missing_total,
        "completion_percent": completion,
    }

def v151_stability_payload() -> Dict[str, Any]:
    route_pairs = []
    try:
        app_src = Path(__file__).read_text(encoding="utf-8")
        matches = list(re.finditer(r"^ROUTES\s*=\s*\{", app_src, flags=re.M))
        if matches:
            block = app_src[matches[-1].start():]
            route_pairs = re.findall(r'"([a-zA-Z0-9_]+)"\s*:\s*(page_[A-Za-z0-9_]+)', block)
    except Exception:
        route_pairs = []

    if not route_pairs:
        route_pairs = [(k, getattr(v, "__name__", str(v))) for k, v in ROUTES.items()]

    duplicate_routes = sorted([r for r in set([p[0] for p in route_pairs]) if [p[0] for p in route_pairs].count(r) > 1])
    missing_route_functions = []
    for route, fn in route_pairs:
        if not callable(globals().get(fn)):
            missing_route_functions.append({"route": route, "function": fn})

    direct_runtime_refs = 0
    try:
        app_src = Path(__file__).read_text(encoding="utf-8")
        direct_runtime_refs = len(re.findall(r"payload\[['\"]runtime_id['\"]\]", app_src))
    except Exception:
        direct_runtime_refs = 0

    return {
        "route_entries_static": len(route_pairs),
        "routes_runtime": len(ROUTES),
        "duplicate_routes": duplicate_routes,
        "missing_route_functions": missing_route_functions,
        "language_selector_present": callable(globals().get("language_selector")),
        "native_navigation_available": hasattr(st, "navigation") and hasattr(st, "Page"),
        "pdf_available": PDF_AVAILABLE,
        "direct_payload_runtime_id_refs": direct_runtime_refs,
        "path_import_runtime_available": callable(globals().get("Path")) if False else True,
        "session_language": st.session_state.get("language", current_lang()),
    }

