def v160_da() -> bool:
    return current_lang() == "Dansk"

def v160_health_payload() -> Dict[str, Any]:
    lang_audit = v151_language_audit_payload() if callable(globals().get("v151_language_audit_payload")) else {}
    stability = v151_stability_payload() if callable(globals().get("v151_stability_payload")) else {}
    routes = len(ROUTES)
    missing_funcs = len(stability.get("missing_route_functions", []))
    missing_dk = len(lang_audit.get("missing_danish_labels", []))
    missing_en = len(lang_audit.get("missing_english_labels", []))
    nav_ok = True
    native_available = hasattr(st, "navigation") and hasattr(st, "Page")
    return {
        "routes": routes,
        "groups": len(GROUPS),
        "guards": len(NON_AUTHORITY_GUARD),
        "missing_route_functions": missing_funcs,
        "missing_danish_labels": missing_dk,
        "missing_english_labels": missing_en,
        "language_completion_percent": lang_audit.get("completion_percent", None),
        "native_navigation_available": native_available,
        "navigation_ready": nav_ok and missing_funcs == 0,
        "language_ready": missing_dk == 0 and missing_en == 0,
        "runtime_ready": missing_funcs == 0,
        "pdf_available": PDF_AVAILABLE,
        "direct_payload_runtime_id_refs": stability.get("direct_payload_runtime_id_refs", 0),
    }

