def v160_unique_pages(page_keys: List[str]) -> List[str]:
    out = []
    seen = set()
    for key in page_keys:
        if key in ROUTES and key not in seen:
            out.append(key)
            seen.add(key)
    return out

def v160_native_pages() -> Dict[str, List[Any]]:
    lang = current_lang()
    labels = PAGE_LABELS.get(lang, PAGE_LABELS.get("English", {}))
    used_urls = set()

    def make_page(key: str, icon: str = "•") -> Any:
        title = labels.get(key, key.replace("_", " ").title())
        base_url = key.replace("_", "-")
        url = base_url
        suffix = 2
        while url in used_urls:
            url = f"{base_url}-{suffix}"
            suffix += 1
        used_urls.add(url)
        return st.Page(ROUTES[key], title=title, icon=icon, url_path=url)

    sections = {
        "Product" if lang == "English" else "Produkt": [
            ("v18_product_home", "🏠"),
            ("v18_founder_pro_center", "👤"),
            ("v18_public_demo_mode", "🧭"),
            ("v18_accessibility_center", "♿"),
            ("v18_search_v2_center", "🔎"),
            ("v18_reviewer_pro_center", "🧪"),
            ("v18_product_architecture_center", "🏗️"),
        ],
        "Founder" if lang == "English" else "Founder": [
            ("v17_founder_mission_control", "❤️"),
            ("v17_founder_story_plus", "👤"),
            ("v17_human_timeline", "🕊️"),
            ("v17_why_care_exists_visual", "🌍"),
            ("v17_public_message_center", "✍️"),
        ],
        "Executive" if lang == "English" else "Executive": [
            ("v16_executive_dashboard", "🏆"),
            ("v16_search_everything_center", "🔎"),
            ("v16_platform_status_center", "🟢"),
            ("v16_release_readiness_center", "🚀"),
        ],
        "Human" if lang == "English" else "Menneske": [
            ("human_consequence_center", "❤️"),
            ("interactive_scenario_builder", "🧩"),
            ("hospital_demo_center", "🏥"),
            ("municipality_demo_center", "🏛️"),
        ],
        "Review" if lang == "English" else "Review": [
            ("reviewer_mode", "🧪"),
            ("v151_language_audit_center", "🌐"),
            ("v151_stability_matrix_center", "🛡️"),
            ("v15_accessibility_center", "♿"),
        ],
        "Story + Downloads" if lang == "English" else "Historie + Downloads": [
            ("v16_founder_story_center", "👤"),
            ("clean_download_center", "📥"),
            ("v15_advanced_archive_center", "🗂️"),
        ],
    }

    result = {}
    for section, pairs in sections.items():
        unique = []
        seen_keys = set()
        for key, icon in pairs:
            if key in ROUTES and key not in seen_keys:
                unique.append(make_page(key, icon))
                seen_keys.add(key)
        result[section] = unique
    return result

