def page_v18_search_v2_center() -> None:
    render_hero("v18_search_v2_center")
    q = st.text_input("Search CARE v2" if not v180_da() else "Søg i CARE v2", value="", placeholder="bind, HOLD, hospital, kommune, founder, accessibility...")
    index = v18_search_index()
    ql = q.strip().lower()
    results = []
    if ql:
        for item in index:
            hay = " ".join(str(v) for v in item.values()).lower()
            if ql in hay:
                results.append(item)
    else:
        results = index[:30]
    rows = []
    for item in results[:120]:
        if v180_da():
            rows.append({"Resultat": item.get("danish_label"), "Type": item.get("function"), "Route": item.get("route"), "Grupper": item.get("groups"), "Grænse": "Søgning ≠ Bind"})
        else:
            rows.append({"Result": item.get("english_label"), "Type": item.get("function"), "Route": item.get("route"), "Groups": item.get("groups"), "Boundary": "Search ≠ Bind"})
    dark_table(rows)
    payload = finalize_report_hash({"module": "v18_search_v2_center", "query": q, "count": len(results), "results": results[:120], "boundary": "Search result is not authority."})
    json_download_button("Download Search v2 JSON", payload, "CARE_v18_0_search_v2")

