def v190_da() -> bool:
    return current_lang() == "Dansk"

def v190_label(en: str, da: str) -> str:
    return da if v190_da() else en

def v190_search_index() -> List[Dict[str, Any]]:
    items = []
    labels_en = PAGE_LABELS.get("English", {})
    labels_da = PAGE_LABELS.get("Dansk", {})

    for route, fn in ROUTES.items():
        hero = HERO.get(route, {})
        groups = [g for g, pages in GROUPS.items() if route in pages]
        items.append({
            "type": "page",
            "title_en": labels_en.get(route, route.replace("_", " ").title()),
            "title_da": labels_da.get(route, route.replace("_", " ").title()),
            "route": route,
            "body_en": " ".join(hero.get("English", ())) + " " + " ".join(groups),
            "body_da": " ".join(hero.get("Dansk", ())) + " " + " ".join(groups),
            "boundary": "Page ≠ Authority",
        })

    for entry in V190_TIMELINE:
        items.append({
            "type": "timeline",
            "title_en": entry["title_en"],
            "title_da": entry["title_da"],
            "route": entry["id"],
            "body_en": f"{entry['year']} {entry['body_en']} {entry['boundary']}",
            "body_da": f"{entry['year']} {entry['body_da']} {entry['boundary']}",
            "boundary": entry["boundary"],
        })

    for concept in V190_CONCEPTS:
        items.append({
            "type": "concept",
            "title_en": concept["label_en"],
            "title_da": concept["label_da"],
            "route": concept["id"],
            "body_en": f"{concept['parent']} {concept['note_en']}",
            "body_da": f"{concept['parent']} {concept['note_da']}",
            "boundary": "Concept ≠ Bind",
        })

    safe_messages = [
        ("CARE is about people before systems.", "CARE handler om mennesker før systemer.", "Mission ≠ Deployment"),
        ("No proof -> no bind -> no effect-capable path -> no effect.", "Ingen bevis -> ingen bind -> ingen effect-capable path -> ingen effekt.", "Rule ≠ Execution"),
        ("No bind -> no human consequence.", "Ingen bind -> ingen menneskelig konsekvens.", "Message ≠ Authority"),
        ("Founder story is context, not authority.", "Founder-historie er kontekst, ikke autoritet.", "Story ≠ Authority"),
    ]
    for idx, (en, da, boundary) in enumerate(safe_messages, 1):
        items.append({
            "type": "public copy",
            "title_en": f"Public message {idx}",
            "title_da": f"Offentlig besked {idx}",
            "route": f"public_message_{idx}",
            "body_en": en,
            "body_da": da,
            "boundary": boundary,
        })
    return items

