def page_v19_global_search_pro() -> None:
    render_hero("v19_global_search_pro")
    q = st.text_input(v190_label("Search CARE", "Søg i CARE"), value="", placeholder="bind, HOLD, founder, hospital, kommune, vNEXT858...")
    index = v190_search_index()
    ql = q.strip().lower()

    if ql:
        results = [item for item in index if ql in " ".join(str(v) for v in item.values()).lower()]
    else:
        results = index[:40]

    rows = []
    for item in results[:150]:
        rows.append({
            v190_label("Type", "Type"): item["type"],
            v190_label("Search result", "Søgeresultat"): item["title_da"] if v190_da() else item["title_en"],
            "Route/ID": item["route"],
            v190_label("Content", "Indhold"): item["body_da"] if v190_da() else item["body_en"],
            v190_label("Boundary", "Grænse"): item["boundary"],
        })
    st.caption(v190_label(f"{len(results)} result(s). Search result is not authority.", f"{len(results)} resultat(er). Søgeresultat er ikke autoritet."))
    dark_table(rows)

    payload = finalize_report_hash({"module": "v19_global_search_pro", "query": q, "count": len(results), "results": results[:150], "boundary": "Search is not authority."})
    json_download_button("Download Global Search JSON", payload, "CARE_v19_0_global_search")

