def main() -> None:
    v129_apply_professional_css()
    v190_render_nav_header()
    language_selector()

    if hasattr(st, "navigation") and hasattr(st, "Page"):
        try:
            pg = st.navigation(v190_native_pages(), position="sidebar", expanded=True)
            pg.run()
            footer()
            return
        except Exception:
            st.sidebar.success("Navigation Ready · fallback router active")

    page_key = sidebar()
    route_fn = ROUTES.get(page_key)
    if callable(route_fn):
        route_fn()
    else:
        page_missing_route_guard(page_key)
    v128_render_completion_overlay(page_key)
    render_current_page_pdf(page_key)
    footer()

if __name__ == "__main__":
    main()
